/* Данные. p — родитель, под которым человек стоит на древе; par — оба родителя (id или текст);
   sp — супруги [ссылка, примечание, тип: m брак (по умолчанию), b помолвка, l связь вне брака];
   k — положение: K король, C претендент, R бастард, B Блэкфайр, T прочие; hs — дом (targ, vel, bar, oth);
   rp — родитель по слухам из другого дома; unc — родство не подтверждено. Годы — от Завоевания. */
const PEOPLE = [
  // ——— Таргариены: владыки Драконьего Камня
  { id: 'aenar', name: 'Эйнар', full: 'Эйнар Изгнанник', en: 'Aenar the Exile', k: 'T', pre: 1,
    t: 'Эйнар принадлежал к одному из сорока домов драконьих владык Валирии. Поверив вещему сну дочери Дейенис, он продал свои владения и в 114 году до Завоевания переселился с семьёй, богатствами и пятью драконами на Драконий Камень. Через двенадцать лет Валирия погибла, а его потомки сохранили свою династию и драконов.' },
  { id: 'daenys', p: 'aenar', name: 'Дейенис', full: 'Дейенис Сновидица', en: 'Daenys the Dreamer', k: 'T', pre: 1, sp: [['gaemon']],
    t: 'Дочь Эйнара Изгнанника, предвидевшая во сне гибель Валирии. Отец принял её предупреждение всерьёз и увёз семью на Драконий Камень. Дейенис вышла за своего брата Гейемона; их потомками были будущие завоеватели Вестероса. Ей приписывают книгу пророческих снов «Знаки и предзнаменования».' },
  { id: 'gaemon', p: 'aenar', name: 'Гейемон', full: 'Гейемон Славный', en: 'Gaemon the Glorious', k: 'T', pre: 1, sp: [['daenys']],
    t: 'Сын Эйнара Изгнанника и муж своей сестры Дейенис Сновидицы. Унаследовал Драконий Камень после отца и вошёл в историю как Гейемон Славный. Хроники сохраняют его имя и место в родословной, но почти не рассказывают о событиях его правления.' },
  { id: 'aegon_l', p: 'gaemon', par: ['gaemon', 'daenys'], name: 'Эйгон', full: 'Эйгон, лорд Драконьего Камня', en: 'Aegon', k: 'T', pre: 1, sp: [['elaena_l']],
    t: 'Сын Гейемона Славного и Дейенис Сновидицы. После смерти отца правил Драконьим Камнем вместе с сестрой и женой Элейной. Их сыновья Мейгон и Эйерис впоследствии поочерёдно наследовали остров. Этот Эйгон жил задолго до Завоевателя.' },
  { id: 'elaena_l', p: 'gaemon', par: ['gaemon', 'daenys'], name: 'Элейна', full: 'Элейна, леди Драконьего Камня', en: 'Elaena', k: 'T', pre: 1, sp: [['aegon_l']],
    t: 'Дочь Гейемона и Дейенис, жена и соправительница своего брата Эйгона. Вместе они возглавляли дом Таргариенов в столетие между Роком Валирии и Завоеванием Вестероса. Известны имена их сыновей, Мейгона и Эйериса; подробности жизни Элейны в хрониках не сохранились.' },
  { id: 'maegon', p: 'aegon_l', par: ['aegon_l', 'elaena_l'], name: 'Мейгон', en: 'Maegon', k: 'T', pre: 1,
    t: 'Сын Эйгона и Элейны, унаследовавший Драконий Камень после родителей. Затем владение перешло к его брату Эйерису. О его семье и делах известно слишком мало, чтобы восстановить подробную биографию.' },
  { id: 'aerys_l', p: 'aegon_l', par: ['aegon_l', 'elaena_l'], name: 'Эйерис', full: 'Эйерис, лорд Драконьего Камня', en: 'Aerys', k: 'T', pre: 1,
    t: 'Сын Эйгона и Элейны, ставший лордом Драконьего Камня после брата Мейгона. Его три сына, Эйликс, Бейлон и Деймион, правили островом один за другим. Через младшего из них продолжилась линия, к которой принадлежал Эйгон Завоеватель.' },
  { id: 'aelyx', p: 'aerys_l', name: 'Эйликс', en: 'Aelyx', k: 'T', pre: 1,
    t: 'Старший сын лорда Эйериса, унаследовавший Драконий Камень после отца. После него островом правили его братья Бейлон и Деймион. Это братья Эйликса, а не его сыновья; других подробностей о нём хроники почти не сообщают.' },
  { id: 'baelon_l', p: 'aerys_l', name: 'Бейлон', full: 'Бейлон, лорд Драконьего Камня', en: 'Baelon', k: 'T', pre: 1,
    t: 'Второй сын лорда Эйериса и один из правителей Драконьего Камня до Завоевания. Наследовал старшему брату Эйликсу, а после него лордом стал младший брат Деймион. Его не следует путать с Бейлоном Отважным, отцом Визериса I и Деймона.' },
  { id: 'daemion', p: 'aerys_l', name: 'Деймион', en: 'Daemion', k: 'T', pre: 1,
    t: 'Младший из трёх сыновей лорда Эйериса. Получил Драконий Камень после братьев Эйликса и Бейлона и передал его своему сыну Эйриону. Через Эйриона он стал дедом Эйгона Завоевателя, Висеньи и Рейенис.' },
  { id: 'aerion_l', p: 'daemion', name: 'Эйрион', full: 'Эйрион, отец Завоевателя', en: 'Aerion', k: 'T', pre: 1, sp: [['valaena']],
    t: 'Лорд Драконьего Камня, муж Валейны Веларион и отец Висеньи, Эйгона и Рейенис. Его дети завоевали большую часть Вестероса и основали королевскую династию. Ориса Баратеона считали его внебрачным сыном, однако хроники передают это как распространённое мнение, а не доказанное родство.' },

  // ——— Завоеватели
  { id: 'visenya', p: 'aerion_l', par: ['aerion_l', 'valaena'], name: 'Висенья', en: 'Visenya', k: 'T', d: '44', dr: 'Вхагар', sp: [['aegon1']],
    t: 'Старшая сестра и жена Эйгона Завоевателя, всадница Вхагар и искусная воительница, владевшая мечом Тёмная Сестра. Помогала покорять Вестерос и сыграла ключевую роль в создании Королевской гвардии. После смерти Эйниса I вернула из изгнания своего сына Мейгора и поддержала его притязания на престол. Её влияние держалось на военной силе и готовности действовать решительно.' },
  { id: 'aegon1', p: 'aerion_l', par: ['aerion_l', 'valaena'], name: 'Эйгон I', full: 'Эйгон I Завоеватель', en: 'Aegon the Conqueror', k: 'K', n: 1, r: '1–37', d: '37', dr: 'Балерион Чёрный Ужас', sp: [['visenya'], ['rhaenys']],
    t: 'Правитель Драконьего Камня, объединивший под своей властью шесть из семи королевств Вестероса. С помощью сестёр и их драконов разгромил главных противников, основал Королевскую Гавань и сделал Железный трон символом новой монархии. Дорн остался независимым, несмотря на последующие войны. Его сыновья Эйнис и Мейгор оба стали королями, но продолжили дело отца совершенно по-разному.' },
  { id: 'rhaenys', p: 'aerion_l', par: ['aerion_l', 'valaena'], name: 'Рейенис', full: 'Рейенис, жена Завоевателя', en: 'Rhaenys', k: 'T', d: '10', dr: 'Мераксес', sp: [['aegon1']],
    t: 'Младшая сестра и жена Эйгона Завоевателя, мать Эйниса I и всадница Мераксес. Любила музыку и полёты, но участвовала в Завоевании и занималась делами королевства наравне с другими правителями. В 10 году её дракона сбили над Адовым Холмом в Дорне. Точная судьба самой Рейенис после падения неизвестна; хроники предлагают несколько версий её гибели.' },

  { id: 'aenys1', p: 'aegon1', par: ['aegon1', 'rhaenys'], name: 'Эйнис I', en: 'Aenys I', k: 'K', n: 2, r: '37–42', b: '7', d: '42', sp: [['alyssa_v', '22 г.']],
    t: 'Старший сын Эйгона Завоевателя и Рейенис, второй король династии. Стремился нравиться подданным и избегал жестоких решений, но оказался неспособен справиться с мятежами. Брак его детей Эйгона и Рейены вызвал восстание Воинства Веры против кровосмешения Таргариенов. Умер на Драконьем Камне, оставив наследнику королевство в состоянии тяжёлого кризиса.' },
  { id: 'maegor1', p: 'aegon1', par: ['aegon1', 'visenya'], name: 'Мейгор I', full: 'Мейгор I Жестокий', en: 'Maegor the Cruel', k: 'K', n: 3, r: '42–48', b: '12', d: '48', dr: 'Балерион',
    sp: [['ceryse', '25 г.'], ['Алис Харроуэй', '39 г.'], ['Тианна с Башни'], ['rhaena_a', '47 г.'], ['Элинор Костейн', '47 г.'], ['Джейн Вестерлинг', '47 г.']],
    t: 'Сын Эйгона и Висеньи, захвативший престол в обход своего племянника Эйгона. На Балерионе подавлял мятежи и воевал с Воинством Веры, прибегая к казням и массовому насилию. При нём завершили Красный замок, после чего строителей убили, чтобы сохранить его тайны. Ни одна из шести жён не родила ему выжившего наследника. Мейгора нашли мёртвым на Железном троне; обстоятельства его смерти остались неясными.' },

  // ——— Дети Эйниса I и Алиссы Веларион
  { id: 'rhaena_a', p: 'aenys1', par: ['aenys1', 'alyssa_v'], name: 'Рейена', full: 'Рейена, дочь Эйниса I', en: 'Rhaena', k: 'T', b: '23', d: '73',
    sp: [['aegon_u', '41 г.'], ['maegor1', '47 г.'], ['Андроу Фарман']],
    t: 'Старшая дочь Эйниса I, всадница Пламени Мечты и жена своего брата Эйгона Некоронованного. После его гибели была вынуждена стать одной из «Чёрных невест» Мейгора. Бежала от него на драконе, забрав меч Чёрное Пламя, и поддержала своего брата Джейехериса. Последующие потери, включая смерть дочери Эйреи, отдалили её от двора; последние годы Рейена прожила в Харренхолле.' },
  { id: 'aegon_u', p: 'aenys1', par: ['aenys1', 'alyssa_v'], name: 'Эйгон', full: 'Эйгон Некоронованный', en: 'Aegon the Uncrowned', k: 'C', b: '26', d: '43', sp: [['rhaena_a', '41 г.']],
    t: 'Старший сын и наследник Эйниса I, муж своей сестры Рейены. После смерти отца законный порядок наследования был нарушен: престол занял его дядя Мейгор. Эйгон попытался вернуть корону и выступил против него на драконе Ртуть. В битве под Божьим Оком Балерион убил Ртуть, а Эйгон погиб, так и не пройдя коронацию.' },
  { id: 'aerea', p: 'aegon_u', par: ['aegon_u', 'rhaena_a'], name: 'Эйрея', en: 'Aerea', k: 'T', d: '56',
    t: 'Дочь Эйгона Некоронованного и Рейены, сестра-близнец Рейеллы. Некоторое время считалась наследницей Джейехериса I, пока у него не появились собственные дети. В 54 году улетела на Балерионе и вернулась в 56 году смертельно больной. Септон Барт предполагал, что дракон унёс её в разрушенную Валирию, но точный маршрут путешествия так и не был установлен.' },
  { id: 'rhaella_a', p: 'aegon_u', par: ['aegon_u', 'rhaena_a'], name: 'Рейелла', full: 'Рейелла, дочь Эйгона Некоронованного', en: 'Rhaella', k: 'T',
    t: 'Дочь Эйгона Некоронованного и Рейены, сестра-близнец Эйреи. Росла при септе в Староместе и посвятила себя служению Семерым. Хроники отмечают резкую перемену в характерах близнецов и передают подозрение, что девочки могли поменяться местами. Подтверждения этой истории нет.' },
  { id: 'viserys_a', p: 'aenys1', par: ['aenys1', 'alyssa_v'], name: 'Визерис', full: 'Визерис, сын Эйниса I', en: 'Viserys', k: 'T', b: '29', d: '44',
    t: 'Младший сын Эйниса I, оказавшийся при дворе Мейгора в положении заложника и оруженосца. Когда его мать Алисса бежала с Джейехерисом и Алисанной, Мейгор приказал подвергнуть Визериса пыткам. Принц умер после девяти дней истязаний. Король оставил его тело во дворе Красного замка, рассчитывая выманить мать из укрытия.' },
  { id: 'jaehaerys1', p: 'aenys1', par: ['aenys1', 'alyssa_v'], name: 'Джейехерис I', full: 'Джейехерис I Миротворец', en: 'Jaehaerys the Conciliator', k: 'K', n: 4, r: '48–103', b: '34', d: '103', dr: 'Вермитор', sp: [['alysanne']],
    t: 'Сын Эйниса I, пришедший к власти после гибели Мейгора и правивший пятьдесят пять лет. Вместе с Алисанной и своими советниками примирил корону с Верой, упорядочил законы и развивал дороги, включая Королевский тракт. Его долгое правление стало временем восстановления и укрепления королевства. Семейная жизнь сложилась гораздо тяжелее: он пережил большинство детей, а спор о наследовании пришлось решать на Великом совете.' },
  { id: 'alysanne', p: 'aenys1', par: ['aenys1', 'alyssa_v'], name: 'Алисанна', full: 'Алисанна, Добрая королева', en: 'Good Queen Alysanne', k: 'T', b: '36', d: '100', dr: 'Среброкрылая', sp: [['jaehaerys1']],
    t: 'Жена и сестра Джейехериса I, известная как Добрая королева. Слушала просьбы женщин и простых подданных, добивалась отмены права первой ночи и расширения земель Ночного Дозора за счёт Нового Дара. На Среброкрылой путешествовала по королевству и участвовала в управлении. Родила тринадцать детей; решения мужа о наследовании не раз становились причиной их ссор.' },
  { id: 'vaella_a', p: 'aenys1', par: ['aenys1', 'alyssa_v'], name: 'Вейелла', full: 'Вейелла, дочь Эйниса I', en: 'Vaella', k: 'T', b: '39',
    t: 'Младшая дочь Эйниса I и Алиссы Веларион. Родилась в 39 году и умерла в раннем детстве. Хроники почти не сохранили сведений о ней; её жизнь пришлась на годы восстания Веры и борьбы внутри династии.' },

  // ——— Дети Джейехериса I и Алисанны
  { id: 'aegon_j', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Эйгон', full: 'Эйгон, сын Джейехериса I', k: 'T', b: '52', d: '52',
    t: 'Первый ребёнок Джейехериса I и Алисанны, родившийся в 52 году. Прожил всего три дня и не успел стать частью придворной жизни. Его смерть была первой из многих семейных потерь, которые пережили король и королева за своё долгое правление.' },
  { id: 'daenerys_j', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Дейенерис', full: 'Дейенерис, дочь Джейехериса I', k: 'T', b: '53', d: '60',
    t: 'Старшая дочь Джейехериса I и Алисанны, родившаяся после смерти их первенца. Королева считала, что дочь имеет право наследовать престол, однако король предпочитал будущего сына. Дейенерис умерла в 60 году во время эпидемии трясучки. Эта потеря показала, что происхождение Таргариенов не защищает их от обычных болезней.' },
  { id: 'aemon_j', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Эймон', full: 'Эймон, сын Джейехериса I', en: 'Aemon', k: 'T', b: '55', d: '92', dr: 'Караксес', sp: [['jocelyn', '70 г.']],
    t: 'Старший из выживших сыновей Джейехериса I, принц Драконьего Камня и всадник Караксеса. Женился на Джоселин Баратеон, единоутробной сестре своих родителей; их единственным ребёнком стала Рейенис. В 92 году погиб на Тарте от арбалетного болта во время борьбы с мирийскими захватчиками. После его смерти король предпочёл его брата Бейлона дочери Рейенис в качестве наследника.' },
  { id: 'baelon_j', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Бейлон', full: 'Бейлон Отважный', en: 'Baelon the Brave', k: 'T', b: '57', d: '101', dr: 'Вхагар', sp: [['alyssa_j', '75 г.']],
    t: 'Сын Джейехериса I и Алисанны, прославившийся как Бейлон Отважный. Был всадником Вхагар, мужем сестры Алиссы и отцом Визериса и Деймона. После смерти Эймона стал наследником престола, позднее занимал пост десницы. Умер в 101 году от внезапной болезни, которую хроники называют «лопнувшим животом»; вслед за этим созвали Великий совет.' },
  { id: 'alyssa_j', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Алисса', full: 'Алисса, дочь Джейехериса I', en: 'Alyssa', k: 'T', b: '60', d: '84', dr: 'Мелейс', sp: [['baelon_j', '75 г.']],
    t: 'Дочь Джейехериса I и Алисанны, жена своего брата Бейлона и всадница Мелейс. Отличалась смелостью и любовью к полётам, даже брала маленьких сыновей с собой на дракона. Родила Визериса, Деймона и Эйгона. После тяжёлых родов третьего ребёнка так и не восстановилась и умерла в 84 году.' },
  { id: 'maegelle', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Мейгелле', full: 'Септа Мейгелле', k: 'T', b: '62',
    t: 'Дочь Джейехериса I и Алисанны, посвятившая жизнь Вере и ставшая септой. Была образованной и мягкой по характеру, поддерживала мать после семейных потерь и дважды помогла примирить родителей. Ухаживала за детьми, больными серой хворью. Заразившись сама, умерла в Староместе в 96 году.' },
  { id: 'vaegon', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Вейегон', full: 'Вейегон Бездраконный', en: 'Vaegon the Dragonless', k: 'T', b: '63',
    t: 'Сын Джейехериса I и Алисанны, предпочитавший книги придворной жизни и воинским занятиям. Не стал всадником дракона и отправился учиться в Цитадель, где получил звание архимейстера. После смерти Бейлона посоветовал отцу передать вопрос о наследовании Великому совету. Прозвище Бездраконный отражает его выбор жизненного пути.' },
  { id: 'daella_j', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Дейелла', full: 'Дейелла, дочь Джейехериса I', k: 'T', b: '64', d: '82', sp: [['rodrik', '80 г.']],
    t: 'Дочь Джейехериса I и Алисанны, застенчивая девушка, которой трудно давались чтение и жизнь при дворе. Из предложенных женихов выбрала лорда Родрика Аррена и переехала в Долину. В 82 году родила Эймму, будущую жену Визериса I, но вскоре умерла от родильной горячки. Через Эймму она стала бабушкой Рейениры.' },
  { id: 'saera', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Саэра', en: 'Saera', k: 'T', b: '67',
    t: 'Дочь Джейехериса I и Алисанны, вступившая в тяжёлый конфликт с отцом после скандала вокруг своих любовных связей. Бежала из Староместа в Лисс, а позднее поселилась в Волантисе и разбогатела, владея увеселительным заведением. С семьёй не примирилась. Трое её внебрачных сыновей заявляли права на престол на Великом совете 101 года, но сама Саэра туда не приехала.' },
  { id: 'viserra', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Визерра', en: 'Viserra', k: 'T', b: '71', d: '87',
    t: 'Дочь Джейехериса I и Алисанны, которую собирались выдать за пожилого лорда Теомора Мандерли. Она сопротивлялась этому браку и пыталась добиться другого положения при дворе. Во время последней ночной прогулки по Королевской Гавани упала с коня и сломала шею. До свадьбы дело не дошло.' },
  { id: 'gaemon_j', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Гейемон', full: 'Гейемон, сын Джейехериса I', k: 'T', b: '73', d: '73',
    t: 'Сын Джейехериса I и Алисанны, родившийся раньше срока в 73 году. Был слабым ребёнком и прожил около трёх месяцев. Его назвали в честь Гейемона Славного, одного из ранних правителей Драконьего Камня.' },
  { id: 'valerion', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Валерион', k: 'T', b: '77', d: '78',
    t: 'Сын Джейехериса I и Алисанны, родившийся в 77 году. Как и несколько других детей королевской пары, умер совсем маленьким, не дожив до первой годовщины рождения. Более подробной истории его жизни хроники не дают.' },
  { id: 'gael', p: 'jaehaerys1', par: ['jaehaerys1', 'alysanne'], name: 'Гаэль', full: 'Гаэль, Дитя зимы', en: 'Gael', k: 'T', b: '80', d: '99',
    t: 'Младшая, тринадцатая дочь Джейехериса I и Алисанны, прозванная Дитя зимы. Была особенно близка с матерью. Двор объявил, что она умерла от лихорадки, но позднее хроника раскрыла другую историю: после связи с певцом и рождения мёртвого ребёнка Гаэль утопилась. Её гибель тяжело отразилась на Алисанне.' },

  // ——— Внуки Джейехериса
  { id: 'rhaenys_q', p: 'aemon_j', par: ['aemon_j', 'jocelyn'], name: 'Рейенис', full: 'Рейенис, Королева, которой никогда не было', en: 'Rhaenys, the Queen Who Never Was', k: 'T', b: '74', d: '129', dr: 'Мелейс', sp: [['corlys', '90 г.']],
    t: 'Дочь принца Эймона и Джоселин Баратеон, жена Корлиса Велариона и всадница Мелейс. После смерти отца её обошли в пользу Бейлона; на Великом совете 101 года главные притязания её ветви представлял сын Лейнор, но победил Визерис. За это Рейенис получила прозвище Королева, которой никогда не было. В Танце драконов поддержала Рейениру и погибла с Мелейс у Грачиного Приюта.' },
  { id: 'viserys1', p: 'baelon_j', par: ['baelon_j', 'alyssa_j'], name: 'Визерис I', en: 'Viserys I', k: 'K', n: 5, r: '103–129', b: '77', d: '129', dr: 'Балерион', sp: [['aemma', '93 г.'], ['alicent', '106 г.']],
    t: 'Внук Джейехериса I, выбранный наследником на Великом совете 101 года. Его правление поначалу сохраняло мир и богатство, накопленные предшественником. После смерти Эйммы объявил наследницей Рейениру, но не изменил этого решения, когда Алисента родила ему сыновей. Соперничество двух ветвей семьи усиливалось при его жизни и после смерти короля переросло в Танец драконов.' },
  { id: 'daemon', p: 'baelon_j', par: ['baelon_j', 'alyssa_j'], name: 'Деймон', full: 'Деймон, Принц Города', en: 'Daemon', k: 'T', b: '81', d: '130', dr: 'Караксес', sp: [['Рея Ройс', '97 г.'], ['laena', '115 г.'], ['rhaenyra', '120 г.']],
    t: 'Младший брат Визериса I, всадник Караксеса и владелец Тёмной Сестры. Командовал золотыми плащами, воевал на Ступенях и на время принял титул короля Ступеней и Узкого моря. После брака с Лейной женился на своей племяннице Рейенире и стал одним из главных военачальников «чёрных». Над Божьим Оком убил Эймонда и исчез вместе с драконами; его тело не нашли, но история о спасении остаётся легендой.' },
  { id: 'aegon_b', p: 'baelon_j', par: ['baelon_j', 'alyssa_j'], name: 'Эйгон', full: 'Эйгон, сын Бейлона', k: 'T', b: '84', d: '84',
    t: 'Младший сын Бейлона Отважного и Алиссы Таргариен. Родился в 84 году; мать умерла после этих тяжёлых родов. Эйгон умер в 85 году, не дожив до первого дня рождения. Его старшие братья, Визерис и Деймон, впоследствии стали центральными фигурами династической истории.' },

  // ——— Дети Визериса I
  { id: 'rhaenyra', p: 'viserys1', par: ['viserys1', 'aemma'], name: 'Рейенира', full: 'Рейенира, Отрада Королевства', en: 'Rhaenyra', k: 'C', fem: 1, b: '97', d: '130', dr: 'Сиракс', sp: [['laenor', '114 г.'], ['daemon', '120 г.']],
    t: 'Единственная выжившая дочь Визериса I от Эйммы Аррен, объявленная наследницей в 105 году. После смерти отца её сторонники короновали её на Драконьем Камне, тогда как «зелёные» возвели на престол Эйгона II. В Танце драконов Рейенира ненадолго заняла Королевскую Гавань, но восстание вынудило её бежать. На Драконьем Камне Эйгон II приказал скормить её Солнечному Огню на глазах у её сына Эйгона.' },
  { id: 'baelon_v', p: 'viserys1', par: ['viserys1', 'aemma'], name: 'Бейлон', full: 'Бейлон, Наследник на день', k: 'T', b: '105', d: '105',
    t: 'Сын Визериса I и Эйммы Аррен, на которого король возлагал надежды как на наследника. Родился в 105 году и умер вскоре после матери. После этой двойной потери Визерис отстранил брата Деймона от наследования и назвал наследницей Рейениру. Прозвище «Наследник на день» связано с приписываемой Деймону насмешкой.' },
  { id: 'aegon2', p: 'viserys1', par: ['viserys1', 'alicent'], name: 'Эйгон II', en: 'Aegon II', k: 'K', n: 6, r: '129–131', b: '107', d: '131', dr: 'Солнечный Огонь', sp: [['helaena'], ['cassandra', 'помолвка после смерти Хелейны', 'b']],
    t: 'Старший сын Визериса I и Алисенты, коронованный «зелёными» вопреки решению отца оставить престол Рейенире. В бою у Грачиного Приюта получил тяжёлые ожоги, позднее снова пострадал при захвате Драконьего Камня. Казнил Рейениру с помощью Солнечного Огня и вернулся в столицу, но не смог завершить войну победой. В 131 году был отравлен; престол унаследовал сын его соперницы.' },
  { id: 'helaena', p: 'viserys1', par: ['viserys1', 'alicent'], name: 'Хелейна', en: 'Helaena', k: 'T', b: '109', d: '130', sp: [['aegon2']],
    t: 'Дочь Визериса I и Алисенты, жена своего брата Эйгона II и всадница Пламени Мечты. В книгах у неё трое детей: близнецы Джейехерис и Джейхейра и младший Мейлор. Убийство Джейехериса Кровью и Сыром сломило её, после чего она почти отошла от жизни двора. Погибла, упав из окна Твердыни Мейгора; хроники связывают это с самоубийством, но передают и другие слухи.' },
  { id: 'aemond', p: 'viserys1', par: ['viserys1', 'alicent'], name: 'Эймонд', full: 'Эймонд Одноглазый', en: 'Aemond One-Eye', k: 'T', b: '110', d: '130', dr: 'Вхагар',
    t: 'Сын Визериса I и Алисенты, потерявший глаз в детской драке после того, как оседлал Вхагар. В Танце драконов убил Люцериса и стал регентом при тяжело раненном Эйгоне II. На Вхагар разорял Речные земли, пытаясь сломить сопротивление «чёрных». Погиб над Божьим Оком, когда Деймон перескочил с Караксеса на Вхагар и поразил его Тёмной Сестрой.' },
  { id: 'daeron_d', p: 'viserys1', par: ['viserys1', 'alicent'], name: 'Дейерон', full: 'Дейерон Отважный', en: 'Daeron the Daring', k: 'T', b: '114', d: '130', dr: 'Тессарион',
    t: 'Младший сын Визериса I и Алисенты, воспитанный в Староместе при дворе Хайтауэров. На Тессарион помог войскам «зелёных» и за храбрость получил прозвище Отважный. Его вмешательство принесло победу у Медовички, но позднее он не сумел предотвратить жестокости своей армии. Погиб во время Второй битвы при Тамблтоне; источники расходятся в обстоятельствах смерти.' },

  // ——— Дети Деймона и Лейны Веларион
  { id: 'baela', p: 'daemon', par: ['daemon', 'laena'], name: 'Бейла', en: 'Baela', k: 'T', b: '116', dr: 'Лунная Плясунья', sp: [['jacaerys', 'помолвка', 'b'], ['alyn']],
    t: 'Дочь Деймона и Лейны, сестра-близнец Рейены и внучка Корлиса Велариона. Была обручена с Джекейрисом, но он погиб до свадьбы. На Лунной Плясунье вступила в бой с Эйгоном II и Солнечным Огнём, пережила гибель дракона и плен. После войны вышла за Элина Велариона, отказавшись от брака, который для неё выбрали регенты.' },
  { id: 'rhaena_d', p: 'daemon', par: ['daemon', 'laena'], name: 'Рейена', full: 'Рейена, дочь Деймона', en: 'Rhaena', k: 'T', b: '116', sp: [['lucerys', 'помолвка', 'b'], ['garmund']],
    t: 'Дочь Деймона и Лейны, сестра-близнец Бейлы. Во время Танца драконов находилась под защитой Джейны Аррен в Долине, где из привезённого ею яйца вылупилось Утро. Пережила войну и стала первой женой сира Корвина Корбрея, а после его гибели вышла за Гармунда Хайтауэра. От второго брака у неё было шесть дочерей.' },
  { id: 'son_laena', p: 'daemon', par: ['daemon', 'laena'], name: 'Сын Лейны', full: 'Сын Деймона и Лейны', k: 'T', b: '120', d: '120',
    t: 'Безымянный сын Деймона Таргариена и Лейны Веларион, младший брат Бейлы и Рейены. Родился после тяжёлых родов и вскоре умер. Лейна также не смогла оправиться и умерла от родильной горячки. Имени ребёнка и других подробностей его короткой жизни хроники не сохранили.' },

  // ——— Дети Рейениры
  { id: 'jacaerys', p: 'rhaenyra', par: ['laenor', 'rhaenyra'], name: 'Джекейрис', full: 'Джекейрис Веларион', en: 'Jacaerys Velaryon', k: 'T', b: '114', d: '130', dr: 'Вермакс', sp: [['baela', 'помолвка', 'b']],
    t: 'Старший сын Рейениры и её наследник, всадник Вермакса. Официально был сыном Лейнора Велариона, хотя его внешность и близость матери с Харвином Стронгом порождали слухи о другом отце. Заключал союзы для «чёрных», в том числе Пакт Льда и Пламени с Криганом Старком, и поддержал поиск новых всадников для драконов. Погиб в битве в Глотке, пытаясь защитить корабли Веларионов.' },
  { id: 'lucerys', p: 'rhaenyra', par: ['laenor', 'rhaenyra'], name: 'Люцерис', full: 'Люцерис Веларион', en: 'Lucerys Velaryon', k: 'T', b: '115', d: '129', dr: 'Арракс', sp: [['rhaena_d', 'помолвка', 'b']],
    t: 'Второй сын Рейениры, официальный наследник Дрифтмарка и всадник Арракса. В детстве во время драки лишил Эймонда глаза, что стало причиной их долгой вражды. В начале Танца отправился послом к Борросу Баратеону и встретил там Эймонда. Боррос не позволил убить гостя в замке, но над заливом Разбитых Кораблей Вхагар настигла Арракса; Люцерис погиб вместе с драконом.' },
  { id: 'joffrey', p: 'rhaenyra', par: ['laenor', 'rhaenyra'], name: 'Джоффри', full: 'Джоффри Веларион', en: 'Joffrey Velaryon', k: 'T', b: '117', d: '130', dr: 'Тираксес',
    t: 'Младший из трёх сыновей Рейениры, носивших фамилию Веларион, всадник Тираксеса. Во время восстания в столице хотел спасти своего дракона из Драконьего логова. Не дождавшись разрешения матери, взлетел на Сиракс, которая не приняла чужого всадника и сбросила его. Джоффри погиб при падении на улицы Королевской Гавани.' },
  { id: 'aegon3', p: 'rhaenyra', par: ['daemon', 'rhaenyra'], name: 'Эйгон III', full: 'Эйгон III Драконья Погибель', en: 'Aegon the Dragonbane', k: 'K', n: 7, r: '131–157', b: '120', d: '157', sp: [['jaehaera', '131 г.'], ['daenaera', '133 г.']],
    t: 'Сын Рейениры и Деймона, переживший Танец драконов и казнь матери. Взошёл на престол ребёнком; первые годы королевством управляли регенты, а сам он тяжело переживал потери войны. В его правление умер последний дракон Таргариенов, за что короля прозвали Драконьей Погибелью, хотя его вина в этом не установлена. Первый брак с Джейхейрой остался бездетным; пятеро его детей родились от Дейенейры Веларион.' },
  { id: 'viserys2', p: 'rhaenyra', par: ['daemon', 'rhaenyra'], name: 'Визерис II', en: 'Viserys II', k: 'K', n: 10, r: '171–172', b: '122', d: '172', sp: [['Ларра Рогаре из Лисса']],
    t: 'Младший сын Рейениры и Деймона, захваченный в детстве во время битвы в Глотке и долго считавшийся погибшим. Вернулся из Лисса с женой Ларрой Рогаре и позднее стал десницей своего брата Эйгона III и его сыновей. Во многом именно он обеспечивал повседневное управление королевством. Получив корону после Бейелора I, правил лишь около года; версия об отравлении сыном остаётся подозрением хронистов.' },
  { id: 'visenya_r', p: 'rhaenyra', par: ['daemon', 'rhaenyra'], name: 'Висенья', full: 'Висенья, дочь Рейениры', k: 'T', b: '129', d: '129',
    t: 'Дочь Рейениры и Деймона, родившаяся мёртвой после известия о смерти Визериса I и коронации Эйгона II. Роды были преждевременными и тяжёлыми. Рейенира назвала ребёнка в честь Висеньи, сестры Эйгона Завоевателя. Эта потеря стала для неё одной из первых личных трагедий Танца драконов.' },

  // ——— Дети Эйгона II
  { id: 'jaehaerys_a', p: 'aegon2', par: ['aegon2', 'helaena'], name: 'Джейехерис', full: 'Джейехерис, сын Эйгона II', k: 'T', b: '123', d: '129',
    t: 'Старший сын Эйгона II и Хелейны, близнец Джейхейры и наследник «зелёной» ветви династии. Был связан с молодым драконом Шрикос, но не успел стать полноценным всадником. Наёмники Кровь и Сыр убили его в Красном замке в отместку за гибель Люцериса. В книгах они сначала заставили Хелейну выбрать одного из сыновей, а затем убили другого.' },
  { id: 'jaehaera', p: 'aegon2', par: ['aegon2', 'helaena'], name: 'Джейехейра', en: 'Jaehaera', k: 'T', b: '123', d: '133', sp: [['aegon3', '131 г.']],
    t: 'Дочь Эйгона II и Хелейны, сестра-близнец Джейехериса. Пережила войну и в 131 году стала женой Эйгона III, что символически соединяло две враждовавшие ветви семьи. В 133 году погибла, упав на колья в сухом рву Твердыни Мейгора. Официальная версия говорила о самоубийстве, но хроники передают серьёзные подозрения в убийстве.' },
  { id: 'maelor', p: 'aegon2', par: ['aegon2', 'helaena'], name: 'Мейлор', en: 'Maelor', k: 'T', b: '127', d: '130',
    t: 'Младший сын Эйгона II и Хелейны. После захвата столицы «чёрными» сир Рикард Торн пытался вывезти мальчика в безопасное место. На Горьком Мосту их узнали, и началась драка за обещанную награду. Мейлор погиб в давке и насилии толпы; хронисты по-разному описывают его последние минуты.' },

  // ——— Дети Эйгона III и Дейенейры Веларион
  { id: 'daeron1', p: 'aegon3', par: ['aegon3', 'daenaera'], name: 'Дейерон I', full: 'Дейерон I Юный Дракон', en: 'Daeron the Young Dragon', k: 'K', n: 8, r: '157–161', b: '143', d: '161',
    t: 'Старший сын Эйгона III, вступивший на престол подростком и получивший прозвище Юный Дракон. Без живых драконов сумел завоевать Дорн военной силой, но удержать его оказалось гораздо труднее. Восстание вынудило короля вернуться к войне, и он погиб во время переговоров с дорнийцами. Детей не оставил; престол перешёл к его брату Бейелору.' },
  { id: 'baelor1', p: 'aegon3', par: ['aegon3', 'daenaera'], name: 'Бейелор I', full: 'Бейелор I Благословенный', en: 'Baelor the Blessed', k: 'K', n: 9, r: '161–171', b: '144', d: '171', sp: [['daena', 'брак расторгнут']],
    t: 'Сын Эйгона III, известный как Бейелор Благословенный. После войны брата заключил мир с Дорном и пешком отправился освобождать пленённого Эймона Рыцаря-Дракона. Ради религиозных убеждений расторг собственный брак и заточил сестёр в Девичьем склепе. Велел строить Великую септу, завершённую уже после его смерти. Умер во время длительного поста; слухи об отравлении не доказаны.' },
  { id: 'daena', p: 'aegon3', par: ['aegon3', 'daenaera'], name: 'Дейена', full: 'Дейена Непокорная', en: 'Daena the Defiant', k: 'T', b: '145', sp: [['baelor1', 'брак расторгнут']],
    t: 'Старшая дочь Эйгона III, смелая и своевольная принцесса, прозванная Непокорной. Была женой своего брата Бейелора, но после его восшествия брак расторгли, а её вместе с сёстрами заперли в Девичьем склепе. Не раз покидала заточение тайком и родила от Эйгона IV сына Деймона. Именно он впоследствии основал дом Блэкфайров.' },
  { id: 'rhaena_b', p: 'aegon3', par: ['aegon3', 'daenaera'], name: 'Рейена', full: 'Рейена, дочь Эйгона III', k: 'T', b: '147',
    t: 'Дочь Эйгона III и Дейенейры, сестра Дейены и Элейны. Бейелор заточил всех троих в Девичьем склепе, стремясь оградить двор от искушений. В отличие от сестёр, Рейена тяготела к религиозной жизни и после освобождения стала септой. Её не следует путать с Рейеной, дочерью Деймона и всадницей Утра.' },
  { id: 'elaena_b', p: 'aegon3', par: ['aegon3', 'daenaera'], name: 'Элейна', full: 'Элейна, дочь Эйгона III', en: 'Elaena', k: 'T', b: '150',
    sp: [['alyn', 'возлюбленный', 'l'], ['Оссифер Пламм', '176 г.'], ['Роннел Пенроуз'], ['Майкл Манвуди']],
    t: 'Младшая дочь Эйгона III, проведшая юность в Девичьем склепе. От Элина Велариона родила близнецов Джона и Джейн Уотерс, а позднее трижды выходила замуж. Обладала способностями к управлению деньгами и фактически помогала выполнять обязанности мастера над монетой своему мужу Роннелу Пенроузу. Прожила долгую жизнь и стала родоначальницей нескольких связанных с Таргариенами ветвей.' },
  { id: 'viserys_pl', p: 'elaena_b', par: ['Оссифер Пламм (по слухам — Эйгон IV)', 'elaena_b'], name: 'Визерис Пламм', en: 'Viserys Plumm', k: 'T', hs: 'oth', h: 'Пламмов',
    t: 'Сын Элейны Таргариен, официально считавшийся ребёнком её первого мужа Оссифера Пламма. Оссифер умер вскоре после свадьбы, и необычные обстоятельства рождения Визериса породили слух, что настоящим отцом был Эйгон IV. Доказательств этого нет. Через дом Пламмов с этой ветвью связывает своё происхождение Бурый Бен Пламм.' },

  // ——— Дети Визериса II и Ларры Рогаре
  { id: 'aegon4', p: 'viserys2', par: ['viserys2', 'Ларра Рогаре'], name: 'Эйгон IV', full: 'Эйгон IV Недостойный', en: 'Aegon the Unworthy', k: 'K', n: 11, r: '172–184', b: '135', d: '184', sp: [['naerys', '153 г.']],
    t: 'Сын Визериса II, вошедший в историю как Эйгон Недостойный. Раздавал должности и милости любимцам, унижал жену Нейерис и сеял сомнения в законности своего наследника Дейерона. Передал меч Чёрное Пламя внебрачному сыну Деймону. Перед смертью узаконил всех своих бастардов, включая детей незнатных женщин; это решение создало основу для многолетних восстаний Блэкфайров.' },
  { id: 'aemon_dk', p: 'viserys2', par: ['viserys2', 'Ларра Рогаре'], name: 'Эймон', full: 'Эймон Рыцарь-Дракон', en: 'Aemon the Dragonknight', k: 'T', b: '136', d: '178',
    t: 'Младший брат Эйгона IV, рыцарь и позднее лорд-командующий Королевской гвардии. Прославился верностью долгу, храбростью и мастерством владения Тёмной Сестрой. Защищал честь сестры Нейерис; слухи об их любовной связи и его отцовстве по отношению к Дейерону II остались недоказанными. Погиб, защищая Эйгона IV от убийц, несмотря на тяжёлые отношения с братом.' },
  { id: 'naerys', p: 'viserys2', par: ['viserys2', 'Ларра Рогаре'], name: 'Нейерис', en: 'Naerys', k: 'T', b: '138', d: '179', sp: [['aegon4', '153 г.']],
    t: 'Сестра и жена Эйгона IV, мать Дейерона II и принцессы Дейенерис. Была набожной и хрупкой, предпочитала бы служение Вере, но отец устроил её брак с Эйгоном. Тяжело переносила беременности и жестокое отношение мужа. Была близка с братом Эймоном Рыцарем-Драконом, однако обвинения в измене не были доказаны. Умерла после очередных родов.' },

  // ——— Дети Эйгона IV
  { id: 'daeron2', p: 'aegon4', par: ['aegon4', 'naerys'], name: 'Дейерон II', full: 'Дейерон II Добрый', en: 'Daeron the Good', k: 'K', n: 12, r: '184–209', b: '153', d: '209', sp: [['myriah']],
    t: 'Сын Эйгона IV и Нейерис, прозванный Добрым. Вместо новых попыток завоевать Дорн добился его мирного присоединения, опираясь на собственный брак с Мирией Мартелл и брак сестры с Мароном. Его власть оспаривал Деймон Блэкфайр, чьи сторонники использовали слухи о происхождении короля. Победил в Первом восстании Блэкфайров, но в 209 году умер от Великого весеннего мора.' },
  { id: 'twins_n', p: 'aegon4', par: ['aegon4', 'naerys'], name: 'Близнецы', full: 'Близнецы Нейерис', k: 'T', b: '161', d: '161',
    t: 'Двое детей Нейерис и Эйгона, родившихся в 161 году и умерших вскоре после рождения. Сама Нейерис едва пережила эти роды. Бейелор I постился в память о детях, а Эйгона отправили с дипломатической миссией в Браавос, дав его жене время восстановиться. Имена близнецов неизвестны.' },
  { id: 'daenerys_n', p: 'aegon4', par: ['aegon4', 'naerys'], name: 'Дейенерис', full: 'Дейенерис, дочь Эйгона IV', k: 'T', b: '172', sp: [['maron']],
    t: 'Дочь Эйгона IV и Нейерис, младшая сестра Дейерона II. Вышла за Марона Мартелла, и этот союз закрепил мирное присоединение Дорна к Семи Королевствам. С её жизнью связаны Водные Сады, где играли вместе дети знати и простолюдинов. Рассказы о любви Деймона Блэкфайра к ней существуют, но сводить всё его восстание к несостоявшемуся браку было бы неточно.' },
  { id: 'daemon_bf', p: 'aegon4', par: ['aegon4', 'daena'], name: 'Деймон I Блэкфайр', en: 'Daemon I Blackfyre', k: 'B', cl: 1, b: '170', d: '196', sp: [['Рохана из Тироша', '184 г.']],
    t: 'Внебрачный сын Эйгона IV и Дейены, родившийся под именем Деймон Уотерс. Получив от отца меч Чёрное Пламя, взял его название как фамилию и стал символом альтернативной ветви династии. В 196 году поднял восстание против Дейерона II. Погиб на Краснотравном поле вместе с двумя старшими сыновьями, но его потомки ещё несколько поколений оспаривали Железный трон.' },
  { id: 'aegor', p: 'aegon4', par: ['aegon4', 'Барба Бракен'], name: 'Эйгор Риверс', full: 'Эйгор Риверс, Жгучий Клинок', en: 'Aegor Rivers, Bittersteel', k: 'R', b: '172', sp: [['calla']],
    t: 'Сын Эйгона IV и Барбы Бракен, известный как Лютый Клинок. Поддержал Деймона Блэкфайра и после поражения увёз уцелевших членов его семьи в Тирош. Основал Золотые Мечи, наёмную компанию, сохранявшую верность Блэкфайрам. Его вражда с Бринденом Риверсом соединяла политическое соперничество, старую неприязнь Бракенов и Блэквудов и личные обиды.' },
  { id: 'mya', p: 'aegon4', par: ['aegon4', 'melissa_bw'], name: 'Мейя Риверс', en: 'Mya Rivers', k: 'R', b: '172/173',
    t: 'Старшая дочь Эйгона IV и Мелиссы Блэквуд, сестра Гвенис и Бриндена Риверса. Относилась к Великим бастардам, поскольку её мать происходила из знатного дома. Была узаконена вместе с остальными внебрачными детьми короля. О её дальнейшей судьбе источники почти ничего не сообщают.' },
  { id: 'gwenys', p: 'aegon4', par: ['aegon4', 'melissa_bw'], name: 'Гвенис Риверс', en: 'Gwenys Rivers', k: 'R', b: '173/174',
    t: 'Дочь Эйгона IV и Мелиссы Блэквуд, младшая сестра Мейи и старшая сестра Бриндена Риверса. Как и другие Великие бастарды, получила законный статус по последней воле отца. В отличие от своих знаменитых братьев, почти не появляется в рассказах о борьбе за престол. Подробности её взрослой жизни неизвестны.' },
  { id: 'brynden', p: 'aegon4', par: ['aegon4', 'melissa_bw'], name: 'Бринден Риверс', full: 'Бринден Риверс, Кровавый Ворон', en: 'Brynden Rivers, Bloodraven', k: 'R', b: '175',
    t: 'Сын Эйгона IV и Мелиссы Блэквуд, прозванный Кровавым Вороном. Сражался за Дейерона II против Блэкфайров, а затем служил десницей Эйериса I и Мейкара I, опираясь на разветвлённую сеть осведомителей. За казнь Эйниса Блэкфайра под охранной грамотой был отправлен в Ночной Дозор и стал его лордом-командующим. Позднее исчез за Стеной; в книгах Бран встречает древнего Бриндена в пещере под чардревом.' },
  { id: 'shiera', p: 'aegon4', par: ['aegon4', 'Серенея из Лисса'], name: 'Шира', full: 'Шира Звезда Морей', en: 'Shiera Seastar', k: 'R', b: '178–184',
    t: 'Дочь Эйгона IV и Серенеи из Лисса, известная как Шира Морская Звезда. Славилась красотой, образованностью и глазами разного цвета; ей также приписывали занятия колдовством. Была возлюбленной Бриндена Риверса, но не стала его женой. За её расположение соперничал и Эйгор Риверс, что усиливало вражду братьев.' },

  // ——— Блэкфайры
  { id: 'aegon_bf', p: 'daemon_bf', par: ['daemon_bf', 'Рохана из Тироша'], name: 'Эйгон Блэкфайр', k: 'B', b: '184', d: '196',
    t: 'Старший сын Деймона I Блэкфайра и Роханны из Тироша, близнец Эймона. Отец рассчитывал сделать его наследником своей короны. Во время Первого восстания погиб на Краснотравном поле от стрел людей Кровавого Ворона. Попытка Деймона защитить его стоила жизни и самому претенденту.' },
  { id: 'aemon_bf', p: 'daemon_bf', par: ['daemon_bf', 'Рохана из Тироша'], name: 'Эймон Блэкфайр', k: 'B', b: '184', d: '196',
    t: 'Сын Деймона I Блэкфайра и Роханны, брат-близнец Эйгона. Когда отец и брат погибли на Краснотравном поле, попытался продолжить сражение. Был убит там же. Смерть близнецов передала главные притязания дома их младшим братьям.' },
  { id: 'daemon2_bf', p: 'daemon_bf', par: ['daemon_bf', 'Рохана из Тироша'], name: 'Деймон II', full: 'Деймон II Блэкфайр', k: 'B', cl: 1,
    t: 'Третий сын Деймона I, известный под именем Джон Скрипач. В 212 году прибыл на свадебный турнир в Белых Стенах, где сторонники готовили новое восстание и надеялись вывести дракона из яйца. Заговор раскрыл Кровавый Ворон. Деймон оказался в плену, а его мечта о короне так и не превратилась в полноценную военную кампанию.' },
  { id: 'haegon', p: 'daemon_bf', par: ['daemon_bf', 'Рохана из Тироша'], name: 'Хейгон I', full: 'Хейгон I Блэкфайр', k: 'B', cl: 1, b: '190–193', d: '219',
    t: 'Сын Деймона I, возглавивший Третье восстание Блэкфайров вместе с Лютым Клинком. После поражения сдался, но был убит, хотя сложил оружие. Его сын Деймон III позднее продолжил борьбу за престол. Хроники подчёркивают вероломство убийства Хейгона, не давая столь же ясного ответа обо всех его обстоятельствах.' },
  { id: 'daemon3_bf', p: 'haegon', name: 'Деймон III', full: 'Деймон III Блэкфайр', k: 'B', cl: 1, d: '236',
    t: 'Старший сын Хейгона, один из претендентов дома Блэкфайров на Железный трон. В 236 году возглавил Четвёртое восстание при поддержке Лютого Клинка. Вторжение быстро потерпело поражение, и Деймон погиб от руки сира Дункана Высокого. После этого притязания дома сохранялись преимущественно в изгнании.' },
  { id: 'aenys_bf', p: 'daemon_bf', par: ['daemon_bf', 'Рохана из Тироша'], name: 'Эйнис Блэкфайр', k: 'B', cl: 1, d: '233',
    t: 'Сын Деймона I, решивший добиваться короны через Великий совет 233 года. Бринден Риверс обещал ему безопасный проезд, но по прибытии приказал схватить и казнить. Эйгон V счёл нарушение обещания преступлением и отправил Бриндена в Ночной Дозор. История Эйниса показывает, насколько далеко Кровавый Ворон был готов зайти ради защиты своей династии.' },
  { id: 'calla', p: 'daemon_bf', par: ['daemon_bf', 'Рохана из Тироша'], name: 'Калла', full: 'Калла Блэкфайр', k: 'B', sp: [['aegor']],
    t: 'Дочь Деймона I Блэкфайра и Роханны из Тироша. Была обещана в жёны Эйгору Риверсу, единокровному брату её отца и главному стороннику Блэкфайров. Такой союз должен был укрепить связи внутри лагеря претендентов. Подробности её дальнейшей жизни и потомства не установлены.' },
  { id: 'maelys', p: 'daemon_bf', unc: 1, par: ['потомок Деймона I, точная линия неизвестна'], name: 'Мейлис I', full: 'Мейлис I Чудовищный', en: 'Maelys the Monstrous', k: 'B', cl: 1, d: '260',
    t: 'Претендент из дома Блэкфайров, прозванный Чудовищным из-за необычного телосложения и второй головы на плече. Его точное место в родословной дома неизвестно. В составе союза Девятигрошовых королей готовил вторжение в Вестерос и воевал на Ступенях. Убил Ормунда Баратеона, но сам пал от руки Барристана Селми; с ним пресеклась известная мужская линия Блэкфайров.' },

  // ——— Дети Дейерона II и Мирии Мартелл
  { id: 'baelor_b', p: 'daeron2', par: ['daeron2', 'myriah'], name: 'Бейелор', full: 'Бейелор Сломи Копьё', en: 'Baelor Breakspear', k: 'T', b: '170', d: '209', sp: [['Джена Дондаррион']],
    t: 'Старший сын Дейерона II, наследник престола и десница короля. Был выдающимся воином и пользовался уважением за рассудительность и чувство справедливости. На турнире в Эшфорде встал на сторону Дункана Высокого в Суде семерых. Получил смертельную рану в голову, вероятнее всего от удара своего брата Мейкара, и умер после поединка.' },
  { id: 'valarr', p: 'baelor_b', par: ['baelor_b', 'Джена Дондаррион'], name: 'Валарр', full: 'Валарр, Молодой принц', k: 'T', d: '209', sp: [['Кира из Тироша']],
    t: 'Старший сын Бейелора Сломи Копьё и Джены Дондарион. После гибели отца стал наследником своего деда Дейерона II. Был женат на Кире из Тироша, но их дети не выжили. В 209 году Великий весенний мор унёс самого Валарра, его брата Матариса и короля, резко изменив порядок наследования.' },
  { id: 'matarys', p: 'baelor_b', par: ['baelor_b', 'Джена Дондаррион'], name: 'Матарис', k: 'T', d: '209',
    t: 'Младший сын Бейелора Сломи Копьё, брат Валарра. Принадлежал к старшей линии потомков Дейерона II и мог бы унаследовать престол после брата. Умер во время Великого весеннего мора в 209 году. Его смерть вместе с другими потерями открыла дорогу к короне Эйерису I.' },
  { id: 'aerys1', p: 'daeron2', par: ['daeron2', 'myriah'], name: 'Эйерис I', en: 'Aerys I', k: 'K', n: 13, r: '209–221', b: '172', d: '221', sp: [['Эйлинор Пенроуз']],
    t: 'Второй сын Дейерона II, получивший корону после Великого весеннего мора. Предпочитал изучение книг и древних пророчеств повседневным государственным делам, которые в значительной мере поручил Кровавому Ворону. Его правление сопровождалось набегами железнорождённых и новыми выступлениями Блэкфайров. Детей от жены Эйлинор Пенроуз не имел; наследником в итоге стал брат Мейкар.' },
  { id: 'rhaegel', p: 'daeron2', par: ['daeron2', 'myriah'], name: 'Рейегель', k: 'T', sp: [['alys_r']],
    t: 'Третий сын Дейерона II, муж Алис Аррен и отец Эйлора, Эйлоры и Дейеноры. Хроники описывают его как добродушного человека с тяжёлыми душевными расстройствами. При бездетном Эйерисе I считался наследником короны. В 215 году умер, подавившись пищей, и его права перешли к детям.' },
  { id: 'aelor', p: 'rhaegel', par: ['rhaegel', 'alys_r'], name: 'Эйлор', k: 'T', t: 'Сын Рейегеля и Алис Аррен, брат-близнец и муж Эйлоры. После смерти отца стал принцем Драконьего Камня и наследником Эйериса I. В 217 году погиб из-за несчастного случая, в котором была замешана его сестра-жена. Подробности происшествия не раскрыты; для Эйлоры оно стало тяжёлой личной трагедией.' },
  { id: 'aelora', p: 'rhaegel', par: ['rhaegel', 'alys_r'], name: 'Эйлора', k: 'T', t: 'Дочь Рейегеля и Алис Аррен, сестра-близнец и жена Эйлора. После случайной гибели мужа, в которой она была виновна, тяжело переживала случившееся. Некоторое время считалась наследницей Эйериса I. Позднее подверглась нападению на маскараде и покончила с собой; обстоятельства её истории известны лишь в кратком изложении хроники.' },
  { id: 'daenora', p: 'rhaegel', par: ['rhaegel', 'alys_r'], name: 'Дейенора', k: 'T', sp: [['aerion_m']],
    t: 'Младшая дочь Рейегеля и Алис Аррен, сестра Эйлора и Эйлоры. Вышла за своего кузена Эйриона Яркое Пламя и в 232 году родила сына Мейгора. После смерти Мейкара I права её ребёнка обсуждались на Великом совете. Совет предпочёл Эйгона V, опасаясь и долгого регентства, и наследия жестокого Эйриона.' },
  { id: 'maekar1', p: 'daeron2', par: ['daeron2', 'myriah'], name: 'Мейкар I', en: 'Maekar I', k: 'K', n: 14, r: '221–233', d: '233', sp: [['Дианна Дейн']],
    t: 'Младший сын Дейерона II, суровый воин и отец Эйгона V. На Суде семерых в Эшфорде сражался против своего брата Бейелора и, вероятнее всего, нанёс ему смертельный удар. Унаследовал престол бездетного Эйериса I и правил двенадцать лет. В 233 году погиб при штурме Звёздного Пика во время восстания Пиков, оставив сложный спор о наследовании.' },

  // ——— Дети Мейкара I и Дианны Дейн
  { id: 'daeron_dr', p: 'maekar1', par: ['maekar1', 'Дианна Дейн'], name: 'Дейерон', full: 'Дейерон Пьяница', en: 'Daeron the Drunken', k: 'T', b: '190/191', sp: [['Кира из Тироша']],
    t: 'Старший сын Мейкара I, которого называли Пьяницей. Видел тревожные вещие сны и пытался заглушить их вином. На турнире в Эшфорде его ложь о Дункане Высоком помогла спровоцировать Суд семерых. Позднее женился на Кире из Тироша и стал отцом Вейеллы, но умер раньше своего отца, не дождавшись короны.' },
  { id: 'vaella_s', p: 'daeron_dr', par: ['daeron_dr', 'Кира из Тироша'], name: 'Вейелла', full: 'Вейелла Простушка', k: 'T', b: '222',
    t: 'Дочь Дейерона Пьяницы и Киры из Тироша, внучка Мейкара I. После смерти деда могла претендовать на престол по старшей ветви семьи. Великий совет 233 года отверг её права, ссылаясь на её умственную незрелость и неспособность править. Другие подробности её дальнейшей судьбы неизвестны.' },
  { id: 'aerion_m', p: 'maekar1', par: ['maekar1', 'Дианна Дейн'], name: 'Эйрион', full: 'Эйрион Яркое Пламя', en: 'Aerion Brightflame', k: 'T', b: '191–194', d: '232', sp: [['daenora']],
    t: 'Сын Мейкара I, жестокий и высокомерный принц, известный как Яркое Пламя. Его нападение на кукольницу в Эшфорде привело к конфликту с Дунканом Высоким и Суду семерых. Позднее жил в изгнании в Лиссе и женился на кузине Дейеноре. В 232 году выпил дикий огонь, уверенный, что превратится в дракона, и умер, оставив младенца Мейгора.' },
  { id: 'maegor_a', p: 'aerion_m', par: ['aerion_m', 'daenora'], name: 'Мейгор', full: 'Мейгор, сын Эйриона', k: 'T',
    t: 'Сын Эйриона Яркое Пламя и Дейеноры, родившийся в год смерти отца. В 233 году Великий совет рассматривал его права на корону после гибели Мейкара I. Лордов пугали долгое регентство и возможность того, что мальчик унаследует жестокость Эйриона. Королём выбрали Эйгона V; дальнейшая жизнь Мейгора подробно не описана.' },
  { id: 'aemon_m', p: 'maekar1', par: ['maekar1', 'Дианна Дейн'], name: 'Эймон', full: 'Мейстер Эймон', en: 'Maester Aemon', k: 'T', b: '198', d: '300',
    t: 'Третий сын Мейкара I, получивший образование в Цитадели и ставший мейстером. Отказался от предложения короны в 233 году, затем вступил в Ночной Дозор, чтобы его имя не использовали против брата Эйгона V. Много десятилетий служил в Чёрном замке и стал наставником Джона Сноу и Сэмвелла Тарли. Умер на корабле «Коричный ветер» после отплытия из Браавоса, по пути в Староместо.' },
  { id: 'daella_m', p: 'maekar1', par: ['maekar1', 'Дианна Дейн'], name: 'Дейелла', full: 'Дейелла, дочь Мейкара I', k: 'T', b: '199',
    t: 'Старшая дочь Мейкара I и Дианны Дейн, сестра Эйгона V. Позднее вышла замуж и имела детей, однако имя мужа и достоверная родословная её потомков не раскрыты. Поэтому связывать её с конкретными поздними персонажами можно лишь как предположение. В повестях о Дунке и Эгге упоминается прежде всего как член семьи Эгга.' },
  { id: 'aegon5', p: 'maekar1', par: ['maekar1', 'Дианна Дейн'], name: 'Эйгон V', full: 'Эйгон V Невероятный', en: 'Aegon the Unlikely', al: ['Эгг', 'Egg'], k: 'K', n: 15, r: '233–259', b: '200', d: '259', sp: [['betha', '220 г.']],
    t: 'Младший сын Мейкара I, в детстве путешествовавший по Вестеросу как Эгг, оруженосец Дункана Высокого. Эти годы познакомили его с жизнью простых людей и повлияли на будущие реформы. Избран Великим советом 233 года, хотя первоначально стоял далеко от престола. Попытки облегчить положение подданных сталкивались с сопротивлением лордов. Погиб в Летнем Замке во время попытки вернуть драконов; подробности катастрофы остаются неполными.' },
  { id: 'rhae', p: 'maekar1', par: ['maekar1', 'Дианна Дейн'], name: 'Рейе', k: 'T',
    t: 'Младшая дочь Мейкара I и Дианны Дейн, сестра Эгга. В детстве однажды подлила ему любовное зелье, надеясь, что он выберет её, а не Дейеллу. Позднее вышла замуж и родила детей, но их имена и семья мужа не названы. Этот пробел не позволяет уверенно продолжить её ветвь родословной.' },

  // ——— Дети Эйгона V и Беты Блэквуд
  { id: 'duncan', p: 'aegon5', par: ['aegon5', 'betha'], name: 'Дункан', full: 'Дункан Малый, Принц Стрекоз', en: 'Duncan the Small', k: 'T', b: '220–224', d: '259',
    sp: [['lyonel_d', 'разорванная помолвка', 'b'], ['Дженни из Старых Камней', '239 г.']],
    t: 'Старший сын Эйгона V, названный в честь Дункана Высокого и известный как Принц Стрекоз. Отказался от помолвки с дочерью Лайонела Баратеона ради Дженни из Старых Камней. Чтобы сохранить этот брак, уступил права на престол младшему брату Джейехерису. Погиб вместе с отцом при пожаре в Летнем Замке.' },
  { id: 'jaehaerys2', p: 'aegon5', par: ['aegon5', 'betha'], name: 'Джейехерис II', en: 'Jaehaerys II', k: 'K', n: 16, r: '259–262', b: '225', d: '262', sp: [['shaera', '240 г.']],
    t: 'Сын Эйгона V, ставший наследником после отказа старшего брата Дункана. Тайно женился на сестре Шейре вопреки брачным планам отца. Позднее, поверив предсказанию о рождении обещанного принца из линии своих детей, настоял на браке Эйериса и Рейеллы. Его короткое правление пришлось на Войну Девятигрошовых королей, завершившуюся разгромом последнего мужского претендента Блэкфайров.' },
  { id: 'shaera', p: 'aegon5', par: ['aegon5', 'betha'], name: 'Шейра', en: 'Shaera', k: 'T', b: '226', sp: [['jaehaerys2', '240 г.']],
    t: 'Дочь Эйгона V и Беты Блэквуд, жена своего брата Джейехериса II. Они отказались от назначенных им браков и поженились тайно, нарушив политические планы отца. Их детьми стали Эйерис II и Рейелла. Через эту пару продолжилась последняя королевская ветвь Таргариенов.' },
  { id: 'daeron_e', p: 'aegon5', par: ['aegon5', 'betha'], name: 'Дейерон', full: 'Дейерон, сын Эйгона V', k: 'T', b: '228',
    t: 'Младший сын Эйгона V и Беты Блэквуд, рыцарь, отказавшийся от помолвки с Оленной Редвин. Был близок с сиром Джереми Норриджем, с которым вместе участвовал в военных походах. Оба погибли в 251 году во время подавления восстания. Дейерон умер раньше отца и не участвовал в позднейшем споре о престоле.' },
  { id: 'rhaelle', p: 'aegon5', par: ['aegon5', 'betha'], name: 'Рейелль', en: 'Rhaelle', k: 'T', b: '229–234', sp: [['ormund', '245 г.']],
    t: 'Младшая дочь Эйгона V, выданная за Ормунда Баратеона после разрыва помолвки её брата Дункана с дочерью Лайонела. Этот брак помог восстановить отношения короны со Штормовым Пределом. Её сыном был Стеффон, а внуками стали Роберт, Станнис и Ренли. Именно через Рейелль Роберт мог обосновывать свои притязания на Железный трон родством с Таргариенами.' },

  // ——— Дети Джейехериса II и Шейры
  { id: 'aerys2', p: 'jaehaerys2', par: ['jaehaerys2', 'shaera'], name: 'Эйерис II', full: 'Эйерис II Безумный король', en: 'Aerys the Mad King', k: 'K', n: 17, r: '262–283', b: '244', d: '283', sp: [['rhaella']], su: 'robert',
    t: 'Сын Джейехериса II и последний Таргариен, правивший Семи Королевствами до восстания Роберта. В начале правления многое обещал, но постепенно стал подозрительным и жестоким; плен в Сумеречном Доле усилил его страхи. Казнь Рикарда и Брандона Старков и требование выдать Роберта и Эддарда привели к открытому восстанию. При падении столицы приказал сжечь город диким огнём, после чего Джейме Ланнистер убил его.' },
  { id: 'rhaella', p: 'jaehaerys2', par: ['jaehaerys2', 'shaera'], name: 'Рейелла', full: 'Рейелла, жена Эйериса II', en: 'Rhaella', k: 'T', b: '245/246', d: '284', sp: [['aerys2']],
    t: 'Сестра и жена Эйериса II, вступившая с ним в брак по настоянию отца. Пережила выкидыши, смерти младенцев и насилие мужа; из её детей до взрослого возраста дожили Рейегар, Визерис и Дейенерис. В конце восстания Роберта была отправлена на Драконий Камень. Умерла там в 284 году при рождении Дейенерис, незадолго до бегства оставшихся детей в Эссос.' },

  // ——— Дети Эйериса II и Рейеллы
  { id: 'rhaegar', p: 'aerys2', par: ['aerys2', 'rhaella'], name: 'Рейегар', en: 'Rhaegar', k: 'T', b: '259', d: '283', sp: [['elia'], ['lyanna', 'в сериале — тайный брак']],
    t: 'Старший сын Эйериса II и Рейеллы, родившийся во время трагедии в Летнем Замке. Увлекался музыкой, книгами и пророчествами, позднее стал опытным воином. Был женат на Элии Мартелл, но его исчезновение вместе с Лианной Старк вызвало политический кризис, переросший в восстание. Погиб на Трезубце в поединке с Робертом Баратеоном. Книжная история его отношений с Лианной полностью не раскрыта.' },
  { id: 'daeron_a2', p: 'aerys2', par: ['aerys2', 'rhaella'], name: 'Дейерон', full: 'Дейерон, сын Эйериса II', k: 'T', b: '269',
    t: 'Сын Эйериса II и Рейеллы, родившийся в 269 году и проживший около полугода. Его смерть стала одной из череды потерь детей королевской пары. Эйерис искал виновных и даже высказывал подозрения в неверности жены. Эти обвинения характеризуют его нараставшую подозрительность, но не устанавливают истинную причину гибели младенца.' },
  { id: 'viserys3', p: 'aerys2', par: ['aerys2', 'rhaella'], name: 'Визерис III', full: 'Визерис, Король-попрошайка', en: 'Viserys, the Beggar King', k: 'C', b: '276', d: '298',
    t: 'Младший сын Эйериса II, после падения династии вывезенный с Драконьего Камня в Эссос. Считал себя законным королём и годами искал поддержку для возвращения в Вестерос, за что получил прозвище Король-попрошайка. Выдал Дейенерис за кхала Дрого в надежде получить войско. Когда угрожал сестре и требовал обещанной короны, Дрого убил его расплавленным золотом.' },
  { id: 'daenerys', p: 'aerys2', par: ['aerys2', 'rhaella'], name: 'Дейенерис', full: 'Дейенерис Бурерождённая', en: 'Daenerys Stormborn', al: ['Мать драконов', 'Дени'], k: 'C', fem: 1, b: '284', dr: 'Дрогон, Рейегаль, Визерион', sp: [['кхал Дрого'], ['Хиздар зо Лорак', 'в книгах']],
    t: 'Младшая дочь Эйериса II, выросшая в изгнании рядом с братом Визерисом. После смерти Дрого вошла в его погребальный костёр с тремя окаменевшими яйцами и вышла оттуда с живыми драконами. В Эссосе боролась с рабовладением и попыталась управлять Миэрином, столкнувшись с войной, голодом и сопротивлением старой знати. В финале «Танца с драконами» находится в Дотракийском море рядом с Дрогоном; дальнейшая книжная судьба не раскрыта.' },
  { id: 'rhaego', p: 'daenerys', par: ['кхал Дрого', 'daenerys'], name: 'Рейго', en: 'Rhaego', k: 'T', b: '298', d: '298',
    t: 'Сын Дейенерис и кхала Дрого, которому дотракийские прорицательницы предсказывали судьбу великого завоевателя. Родился мёртвым во время событий, связанных с обрядом Мирри Маз Дуур. Дейенерис считала смерть сына ценой попытки спасти Дрого. Описание его тела и объяснение причин гибели переданы через слова Мирри, а не через независимое свидетельство.' },
  { id: 'rhaenys_r', p: 'rhaegar', par: ['rhaegar', 'elia'], name: 'Рейенис', full: 'Рейенис, дочь Рейегара', k: 'T', b: '280', d: '283',
    t: 'Дочь Рейегара и Элии Мартелл, названная в честь сестры Эйгона Завоевателя. Во время разграбления Королевской Гавани пыталась спрятаться в покоях отца. Была убита Амори Лорхом, когда ей было около трёх лет. Вместе с гибелью матери и брата её смерть стала причиной многолетней вражды Мартеллов с Ланнистерами.' },
  { id: 'aegon_r', p: 'rhaegar', par: ['rhaegar', 'elia'], name: 'Эйгон', full: 'Эйгон, сын Рейегара', al: ['Молодой Гриф', 'Эйгон VI'], k: 'T', b: '281', d: '283',
    t: 'Младший ребёнок Рейегара и Элии, считавшийся убитым Григором Клиганом при разграблении столицы. В «Танце с драконами» Молодой Гриф заявляет, что он и есть спасённый Эйгон, подменённый Варисом до гибели города. Его поддерживают Джон Коннингтон и Золотые Мечи. Личность юноши не доказана окончательно, поэтому рассказ о подмене следует воспринимать как заявленную версию.' },
  { id: 'jon', p: 'rhaegar', unc: 1, par: ['rhaegar', 'lyanna'], name: 'Джон Сноу', en: 'Jon Snow', k: 'R', b: '283',
    t: 'Вырос в Винтерфелле как признанный бастард Эддарда Старка, затем вступил в Ночной Дозор и стал его лордом-командующим. Пытался подготовить защиту от Иных и пропустить одичалых через Стену, что вызвало сопротивление части братьев. В конце «Танца с драконами» на него нападают заговорщики; исход нападения в опубликованных романах не раскрыт. Происхождение от Рейегара и Лианны убедительно предполагается читателями, но прямо подтверждено только в сериале.' },

  // ——— Дом Веларионов
  { id: 'valaena', hs: 'vel', name: 'Валейна Веларион', en: 'Valaena Velaryon', k: 'T', sp: [['aerion_l']],
    t: 'Жена Эйриона Таргариена и мать Висеньи, Эйгона Завоевателя и Рейенис. По отцу принадлежала к Веларионам, а её мать была Таргариен. Этот брак отражает давнюю близость двух валирийских домов, а не начало их отношений. Имена родителей Валейны и подробности её собственной жизни не названы.' },
  { id: 'daemon_v0', hs: 'vel', name: 'Деймон Веларион', full: 'Деймон Веларион, мастер над кораблями Завоевателя', en: 'Daemon Velaryon', k: 'T',
    t: 'Лорд Дрифтмарка и адмирал Эйгона Завоевателя. Поддержал Таргариенов во время вторжения в Вестерос и командовал их флотом. Погиб в морском бою у Чаячьего города, где силы Долины разбили корабли завоевателей. Его сын Этан унаследовал владения и должность мастера над кораблями.' },
  { id: 'aethan', p: 'daemon_v0', hs: 'vel', name: 'Этан Веларион', en: 'Aethan Velaryon', k: 'T', sp: [['Аларра Мэсси']],
    t: 'Сын лорда Деймона Велариона, наследовавший Дрифтмарк и командование флотом после гибели отца. Служил мастером над кораблями при Эйгоне I и его преемниках, участвовал в борьбе с пиратом Саргосо Сааном. Его дочь Алисса вышла за Эйниса I и стала королевой. Благодаря этому браку потомки Этана вошли в королевскую династию.' },
  { id: 'corlys_kg', p: 'daemon_v0', hs: 'vel', name: 'Сир Корлис Веларион', full: 'Сир Корлис Веларион, лорд-командующий', en: 'Ser Corlys Velaryon', k: 'T',
    t: 'Брат Этана Велариона и первый лорд-командующий Королевской гвардии. Получил эту должность при создании ордена в правление Эйгона Завоевателя. Его служба стала частью раннего устройства новой монархии. Он жил задолго до Корлиса Морского Змея и является другим представителем того же дома.' },
  { id: 'alyssa_v', p: 'aethan', par: ['aethan', 'Аларра Мэсси'], hs: 'vel', name: 'Алисса Веларион', en: 'Alyssa Velaryon', k: 'T', d: '54', sp: [['aenys1', '22 г.'], ['rogar', '49 г.']],
    t: 'Дочь Этана Велариона, жена Эйниса I и мать шестерых его детей. После смерти мужа спасала семью от Мейгора, а после его гибели стала регентом при юном Джейехерисе. Вторым браком вышла за Рогара Баратеона и родила Боремунда и Джоселин. Умерла после тяжёлых родов Джоселин в 54 году, связав своим потомством дома Таргариенов, Веларионов и Баратеонов.' },
  { id: 'daemon_v', p: 'aethan', par: ['aethan', 'Аларра Мэсси'], hs: 'vel', name: 'Деймон Веларион', full: 'Деймон Веларион, лорд Дрифтмарка', en: 'Daemon Velaryon', k: 'T',
    t: 'Сын Этана и брат королевы Алиссы, лорд Дрифтмарка и командующий королевским флотом. Сначала служил Мейгору, но затем отказался поддерживать его и встал на сторону Джейехериса. При новом короле был мастером над кораблями и некоторое время десницей. Его старший сын Корвин умер раньше него, поэтому Дрифтмарк унаследовал внук Корлис Морской Змей.' },
  { id: 'aethan_sons', p: 'aethan', par: ['aethan', 'Аларра Мэсси'], hs: 'vel', name: 'Другие сыновья Этана', full: 'Другие сыновья Этана Велариона', k: 'T',
    t: 'Несколько сыновей Этана Велариона, чьи имена и отдельные биографии не сохранились. К этой части семьи предположительно относились родители Лианны и Лариссы Веларион. Точную линию родства восстановить нельзя. Их объединение в одну карточку обозначает пробел в источниках, а не известного по имени персонажа.' },
  { id: 'lianna', p: 'aethan_sons', unc: 1, par: ['племянница лорда Деймона Велариона; отец не назван'], hs: 'vel', name: 'Лианна Веларион', en: 'Lianna Velaryon', k: 'T', d: '54',
    t: 'Племянница лорда Деймона Велариона и одна из близких спутниц Рейены Таргариен на Драконьем Камне. В 54 году стала жертвой отравлений, устроенных мужем Рейены Андроу Фарманом. Он убивал женщин из окружения жены, чувствуя себя отвергнутым. Собственная семья Лианны и её ранняя жизнь почти не описаны.' },
  { id: 'larissa', p: 'aethan_sons', unc: 1, par: ['двоюродная сестра Рейены Таргариен; отец не назван'], hs: 'vel', name: 'Ларисса Веларион', en: 'Larissa Velaryon', k: 'T', sp: [['лорд из дома Тартов']],
    t: 'Родственница Веларионов и двоюродная сестра Рейены, дочери Эйниса I. Вышла замуж за представителя дома Тартов и родила дочь. Этот брак связывает раннюю родословную Веларионов со Штормовыми землями. Более подробных сведений о её муже и дальнейшей жизни нет.' },
  { id: 'corwyn', p: 'daemon_v', hs: 'vel', name: 'Корвин Веларион', en: 'Corwyn Velaryon', k: 'T',
    t: 'Старший сын лорда Деймона Велариона и отец Корлиса Морского Змея. Умер раньше отца, поэтому сам не успел унаследовать Дрифтмарк. После смерти Деймона владения перешли непосредственно Корлису. О собственных делах Корвина известно мало; его значение в хрониках прежде всего родословное.' },
  { id: 'jorgen', p: 'daemon_v', hs: 'vel', name: 'Йорген Веларион', en: 'Jorgen Velaryon', k: 'T',
    t: 'Один из сыновей лорда Деймона Велариона, брат Корвина и Виктора. Принадлежал к поколению, предшествовавшему Корлису Морскому Змею. Хроники называют его в составе семьи, но не дают самостоятельного рассказа о его жизни. Приписывать ему конкретные походы или потомков без дополнительных сведений нельзя.' },
  { id: 'victor', p: 'daemon_v', hs: 'vel', name: 'Виктор Веларион', en: 'Victor Velaryon', k: 'T',
    t: 'Сын лорда Деймона Велариона, брат Корвина и Йоргена. Представитель старшей семьи Дрифтмарка в правление Джейехериса I. Его имя сохранилось в семейных сведениях, однако собственная биография почти неизвестна. Достоверно продолжить его ветвь родословной не удаётся.' },
  { id: 'corlys_br1', p: 'corwyn', hs: 'vel', name: 'Старший брат Корлиса', full: 'Старший брат Корлиса Велариона', k: 'T',
    t: 'Безымянный брат Корлиса Морского Змея, отец сира Вейемонда Велариона. Через него происходит ветвь, позднее оспаривавшая наследование Дрифтмарка. Его личная жизнь и служба не описаны. Имя отсутствует в источниках, поэтому карточка обозначает известную семейную связь.' },
  { id: 'corlys', p: 'corwyn', hs: 'vel', name: 'Корлис Веларион', full: 'Корлис Веларион, Морской Змей', en: 'Corlys Velaryon, the Sea Snake', k: 'T', b: '53', d: '132', sp: [['rhaenys_q', '90 г.']],
    t: 'Лорд Дрифтмарка, прославленный мореплаватель и муж Рейенис Таргариен. Девять больших плаваний принесли ему богатство и прозвище Морской Змей; он построил Высокий Прилив и сделал свой дом одним из самых влиятельных в королевстве. В Танце драконов поддерживал Рейениру, но отношения с ней ухудшились после обвинения Аддама в измене. Пережил войну и вошёл в регентский совет Эйгона III.' },
  { id: 'corlys_br2', p: 'corwyn', unc: 1, hs: 'vel', name: 'Другой брат Корлиса', full: 'Другой брат Корлиса Велариона', k: 'T',
    t: 'Ещё один безымянный брат Корлиса Морского Змея. С этой частью семьи предположительно связаны родственники, известные как «молчаливая пятёрка», однако их точное происхождение не раскрыто. Известное родство не позволяет уверенно назвать всех детей этого человека.' },
  { id: 'vaemond', p: 'corlys_br1', hs: 'vel', name: 'Вейемонд Веларион', full: 'Сир Вейемонд Веларион', en: 'Vaemond Velaryon', k: 'T', d: '126',
    t: 'Племянник Корлиса Морского Змея, выступивший против передачи Дрифтмарка Люцерису Велариону. Объявил сыновей Рейениры бастардами и потребовал признать его права. В книжной версии Рейенира приказала убить его, Деймон выполнил приказ, а тело отдали Сиракс. Его казнь и наказание других родственников показали, насколько опасным стал спор о происхождении наследников.' },
  { id: 'daemion_v', p: 'vaemond', hs: 'vel', name: 'Деймион Веларион', en: 'Daemion Velaryon', k: 'T',
    t: 'Старший сын сира Вейемонда Велариона и брат Дейерона. Принадлежал к боковой ветви дома, из которой происходила королева Дейенейра. Его отец погиб из-за спора о наследовании Дрифтмарка. О личной судьбе самого Деймиона хроники сообщают мало.' },
  { id: 'daeron_v', p: 'vaemond', hs: 'vel', name: 'Дейерон Веларион', en: 'Daeron Velaryon', k: 'T', sp: [['Хейзел Харт']],
    t: 'Младший сын Вейемонда Велариона и отец Дейенейры, будущей жены Эйгона III. Сражался на Ступенях в войске Элина Дубового Кулака и погиб в одном из морских столкновений. Его дочь рано осталась сиротой, но позднее стала королевой. Через неё эта боковая ветвь Веларионов вошла в родословную поздних Таргариенов.' },
  { id: 'daenaera', p: 'daeron_v', par: ['daeron_v', 'Хейзел Харт'], hs: 'vel', name: 'Дейенейра Веларион', en: 'Daenaera Velaryon', k: 'T', b: '127', sp: [['aegon3', '133 г.']],
    t: 'Дочь Дейерона Велариона, рано потерявшая родителей. На смотре невест её представили Эйгону III, и он выбрал её своей второй женой. Родила пятерых детей, включая будущих королей Дейерона I и Бейелора I. Через дочь Дейену была бабушкой Деймона Блэкфайра и предком его дома.' },
  { id: 'malentine', p: 'corlys_br2', unc: 1, hs: 'vel', name: 'Малентин Веларион', full: 'Сир Малентин Веларион', en: 'Malentine Velaryon', k: 'T',
    t: 'Родственник Вейемонда и Корлиса из числа пяти Веларионов, которым Визерис I велел вырезать языки за обвинения детей Рейениры в незаконном рождении. После войны выступал против наследования Элина Велариона. Участвовал в заговоре против нового лорда Дрифтмарка и погиб. Его история связана с затянувшимся спором о том, какая ветвь должна владеть островом.' },
  { id: 'rhogar_v', p: 'corlys_br2', unc: 1, hs: 'vel', name: 'Рогар Веларион', full: 'Сир Рогар Веларион', en: 'Rhogar Velaryon', k: 'T',
    t: 'Брат Малентина Велариона и один из родственников, лишённых языков по приказу Визериса I. Позднее участвовал в попытке устранить Элина Велариона, чьё наследование оспаривала их ветвь. Был схвачен после провала заговора. Источники описывают его главным образом через эти семейные конфликты.' },
  { id: 'silent3', p: 'corlys_br2', unc: 1, hs: 'vel', name: 'Ещё трое братьев', full: 'Трое безымянных из «молчаливой пятёрки»', k: 'T',
    t: 'Трое других родственников из «молчаливой пятёрки» Веларионов. Вместе с Малентином и Рогаром повторили обвинение, что дети Рейениры не были сыновьями Лейнора, и лишились языков по приказу Визериса I. Их личные имена не названы. Эта общая карточка сохраняет сведения о наказанной группе.' },
  { id: 'laena', p: 'corlys', par: ['corlys', 'rhaenys_q'], hs: 'vel', name: 'Лейна Веларион', en: 'Laena Velaryon', k: 'T', b: '92', d: '120', dr: 'Вхагар', sp: [['daemon', '115 г.']],
    t: 'Дочь Корлиса Велариона и Рейенис Таргариен, всадница Вхагар. После несостоявшегося брака с Визерисом I стала второй женой Деймона и вместе с ним путешествовала по Вольным городам. Родила близнецов Бейлу и Рейену. В книгах умерла от родильной горячки после рождения сына, пытаясь перед смертью добраться до своего дракона.' },
  { id: 'laenor', p: 'corlys', par: ['corlys', 'rhaenys_q'], hs: 'vel', name: 'Лейнор Веларион', en: 'Laenor Velaryon', k: 'T', b: '94', d: '120', dr: 'Морской Дым', sp: [['rhaenyra', '114 г.']],
    t: 'Сын Корлиса и Рейенис, всадник Морского Дыма. На Великом совете 101 года представлял главные притязания материнской ветви, но уступил Визерису. Женился на Рейенире и официально стал отцом Джекейриса, Люцериса и Джоффри, хотя вокруг их происхождения ходили слухи. В книгах погиб от руки Карла Коррея; возможная причастность Деймона известна лишь как версия.' },
  { id: 'alyn', p: 'corlys', unc: 1, par: ['corlys', 'Марильда из Халла'], hs: 'vel', name: 'Элин Веларион', full: 'Элин Веларион, Дубовый Кулак', en: 'Alyn Velaryon, Oakenfist', k: 'R', sp: [['baela'], ['elaena_b', 'возлюбленная', 'l']],
    t: 'Сын Марильды из Халла, которого она называла ребёнком Лейнора, тогда как другие считали его отцом Корлиса. Был узаконен как Веларион и после гибели брата Аддама унаследовал Дрифтмарк. Прославился морскими походами под прозвищем Дубовый Кулак, женился на Бейле Таргариен и позднее стал отцом близнецов Элейны. Исчез во время плавания; точные обстоятельства смерти неизвестны.' },
  { id: 'addam', p: 'corlys', unc: 1, par: ['corlys', 'Марильда из Халла'], hs: 'vel', name: 'Аддам Веларион', en: 'Addam Velaryon', k: 'R', d: '130', dr: 'Морской Дым',
    t: 'Старший брат Элина из Халла, оседлавший Морской Дым во время поиска новых всадников. Рейенира узаконила его, и Корлис сделал его наследником Дрифтмарка. Когда королева заподозрила драконьих семян в измене, Аддам бежал, но продолжил воевать за неё. Погиб во Второй битве при Тамблтоне, доказав верность делом; позднее на его могиле оставили слово «Верный».' },
  { id: 'laena_a', p: 'alyn', par: ['alyn', 'baela'], hs: 'vel', name: 'Лейна', full: 'Лейна Веларион, дочь Элина', en: 'Laena Velaryon', k: 'T',
    t: 'Дочь Элина Велариона и Бейлы Таргариен, названная в честь своей бабушки Лейны. Её рождение продолжило союз двух валирийских домов после Танца драконов. В детстве ей дали драконье яйцо, но вылупившееся существо оказалось опасным уродливым детёнышем и было убито. Дальнейшая жизнь Лейны подробно не описана.' },
  { id: 'jon_w', p: 'alyn', par: ['alyn', 'elaena_b'], hs: 'vel', name: 'Джон Уотерс', full: 'Сир Джон Уотерс', en: 'Jon Waters', k: 'R',
    t: 'Внебрачный сын Элина Велариона и принцессы Элейны, брат-близнец Джейн. Носил фамилию Уотерс, принятую для признанных бастардов Королевских земель, и стал известным рыцарем. Его законный сын изменил фамилию на Лонгвотерс. Так возникла младшая ветвь, сохранившая родство с Таргариенами и Веларионами.' },
  { id: 'jeyne_w', p: 'alyn', par: ['alyn', 'elaena_b'], hs: 'vel', name: 'Джейн Уотерс', en: 'Jeyne Waters', k: 'R',
    t: 'Внебрачная дочь Элина Велариона и Элейны Таргариен, сестра-близнец Джона Уотерса. Родилась от связи, которая не завершилась браком: Элин пропал в море. В отличие от брата, почти не упоминается в дальнейших событиях. Подробности её собственной семьи неизвестны.' },
  { id: 'longwaters', p: 'jon_w', hs: 'vel', name: 'Сын Джона Уотерса', full: 'Сын Джона Уотерса, основатель дома Лонгвотерс', k: 'T',
    t: 'Законный сын сира Джона Уотерса и внук Элина Велариона и Элейны Таргариен. Добавил к фамилии отца часть «Лонг», чтобы подчеркнуть, что сам рождён в браке. Стал родоначальником дома Лонгвотерс. Один из его поздних потомков, Реннифер Лонгвотерс, служит главным помощником тюремщика в Красном замке.' },
  { id: 'lucerys_v', hs: 'vel', name: 'Люцерис Веларион', full: 'Лорд Люцерис Веларион', en: 'Lucerys Velaryon', k: 'T', sp: [['Реннифер Лонгвотерс', 'из потомков Джона Уотерса']],
    t: 'Лорд Дрифтмарка и мастер над кораблями при Эйерисе II. При дворе поддерживал короля в его соперничестве с наследником Рейегаром. Поздняя родословная Веларионов прослежена неполно, и точную связь Люцериса с потомками Корлиса установить нельзя. Его не следует путать с Люцерисом, сыном Рейениры.' },
  { id: 'monford', p: 'lucerys_v', unc: 1, par: ['lucerys_v (предшественник; родство в книгах не названо)'], hs: 'vel', name: 'Монфорд Веларион', en: 'Monford Velaryon', k: 'T', d: '299',
    t: 'Лорд Дрифтмарка во время Войны пяти королей. Поддержал Станниса Баратеона и привёл свои корабли к Королевской Гавани. Погиб на Черноводной, когда дикий огонь уничтожил его корабль «Гордость Дрифтмарка». Владения перешли к малолетнему сыну Монтерису.' },
  { id: 'aurane', p: 'lucerys_v', unc: 1, par: ['отец Монфорда (не назван)'], hs: 'vel', name: 'Ауран Уотерс', full: 'Ауран Уотерс, Бастард Дрифтмарка', en: 'Aurane Waters', k: 'R',
    t: 'Внебрачный единокровный брат Монфорда Велариона, участвовавший в войне на стороне Станниса. После поражения на Черноводной перешёл к Ланнистерам и получил от Серсеи должность мастера над кораблями. Воспользовавшись её арестом, увёл построенные за королевский счёт корабли. Его бегство показало, насколько ненадёжными были назначения Серсеи.' },
  { id: 'monterys', p: 'monford', hs: 'vel', name: 'Монтерис Веларион', en: 'Monterys Velaryon', k: 'T',
    t: 'Малолетний сын Монфорда Велариона, унаследовавший Дрифтмарк после гибели отца на Черноводной. Стал лордом примерно в шесть лет. Самостоятельной политической роли в опубликованной истории ещё не играет. Его положение подчёркивает потери дома Веларионов в войне.' },

  // ——— Дом Баратеонов
  { id: 'orys', hs: 'bar', rp: 'aerion_l', par: ['aerion_l (по слухам)'], name: 'Орис Баратеон', full: 'Орис Баратеон, Однорукий', en: 'Orys Baratheon', k: 'T', sp: [['Аргелла Дюррандон']],
    t: 'Один из ближайших соратников Эйгона Завоевателя и его первый десница. Считался внебрачным единокровным братом Эйгона, хотя родство не доказано. Победил Аргилака Дюррандона, женился на его дочери Аргелле и принял герб и девиз прежних Штормовых королей. Во время войны в Дорне попал в плен и лишился руки. От него ведёт начало дом Баратеонов.' },
  { id: 'davos_b', p: 'orys', par: ['orys', 'Аргелла Дюррандон'], hs: 'bar', name: 'Давос Баратеон', en: 'Davos Baratheon', k: 'T',
    t: 'Сын Ориса Баратеона и Аргеллы Дюррандон, представитель первого поколения нового дома. Его имя известно, но подробная биография и надёжные сведения о потомках отсутствуют. Предположение, что именно он был отцом Рогара, встречается в реконструкциях, однако уверенно утверждать это нельзя.' },
  { id: 'raymont', p: 'orys', par: ['orys', 'Аргелла Дюррандон'], hs: 'bar', name: 'Реймонт Баратеон', full: 'Сир Реймонт Баратеон', en: 'Raymont Baratheon', k: 'T',
    t: 'Представитель раннего дома Баратеонов, которого «Мир льда и огня» называет сыном Ориса и рыцарем Королевской гвардии, спасшим Эйниса I от убийц. В «Пламени и крови» соответствующий защитник короля остаётся безымянным. Из-за расхождения источников имя и точное положение Раймонта в родословной требуют оговорки. Его история связана с восстанием Воинства Веры.' },
  { id: 'orys_son', p: 'orys', hs: 'bar', name: 'Отец Рогара', full: 'Отец Рогара Баратеона', k: 'T',
    t: 'Безымянный сын Ориса Баратеона и Аргеллы Дюррандон, отец Рогара и его четырёх братьев. Через него продолжается ранняя линия лордов Штормового Предела. Источники не позволяют надёжно отождествить его с одним из названных сыновей Ориса. Поэтому его имя в древе оставлено неизвестным.' },
  { id: 'rogar', p: 'orys_son', hs: 'bar', name: 'Рогар Баратеон', en: 'Rogar Baratheon', k: 'T', d: '62', sp: [['alyssa_v', '49 г.']],
    t: 'Внук Ориса, лорд Штормового Предела и один из первых сторонников юного Джейехериса против Мейгора. Был десницей и лордом-протектором, женился на вдовствующей королеве Алиссе Веларион. Его попытки управлять судьбой молодого короля привели к разрыву, но позднее они примирились. Отец Боремунда и Джоселин, через которых Баратеоны снова сблизились с королевским домом.' },
  { id: 'borys_b', p: 'orys_son', hs: 'bar', name: 'Борис Баратеон', full: 'Сир Борис Баратеон', k: 'T',
    t: 'Старший из младших братьев Рогара, некоторое время считавшийся его наследником. После рождения Боремунда потерял эту перспективу, поссорился с братом и уехал за море. Вернувшись, присоединился к Королю-Стервятнику и совершал набеги на Штормовые земли. В 61 году погиб в поединке с Джейехерисом I, который не хотел заставлять Рогара убивать родного брата.' },
  { id: 'garon_b', p: 'orys_son', hs: 'bar', name: 'Гарон Баратеон', full: 'Сир Гарон Баратеон', k: 'T',
    t: 'Один из младших братьев Рогара Баратеона. Его семья пострадала во время эпидемии трясучки, унёсшей жизнь жены. Хроника упоминает его прежде всего среди родственников лорда Штормового Предела. Имена детей и подробности самостоятельной деятельности неизвестны.' },
  { id: 'ronnal_b', p: 'orys_son', hs: 'bar', name: 'Роннал Баратеон', full: 'Сир Роннал Баратеон', k: 'T',
    t: 'Брат Рогара Баратеона, чья семья тяжело пострадала от трясучки. Болезнь унесла его жену и сыновей, оставив в живых двух дочерей. Эта история входит в описание потерь знати во время эпидемии. Имена дочерей и их дальнейшая судьба не раскрыты.' },
  { id: 'orryn_b', p: 'orys_son', hs: 'bar', name: 'Оррин Баратеон', full: 'Сир Оррин Баратеон', k: 'T', sp: [['alysanne', 'несостоявшийся брак, 49 г.', 'b'], ['дочь тирошийского архонта']],
    t: 'Младший брат Рогара Баратеона. Его рассматривали как возможного мужа Алисанны, но она тайно вышла за Джейехериса. Позднее участвовал в попытке вывезти Рейеллу Таргариен из Староместа, чтобы использовать её права на престол. За это был отправлен в изгнание на десять лет.' },
  { id: 'boremund', p: 'rogar', par: ['rogar', 'alyssa_v'], hs: 'bar', name: 'Боремунд Баратеон', en: 'Boremund Baratheon', k: 'T', b: '51',
    t: 'Сын Рогара и Алиссы Веларион, единоутробный брат Джейехериса I и Алисанны. Унаследовал Штормовой Предел и поддерживал права своей племянницы Рейенис и её сына Лейнора. На Великом совете 101 года стоял на стороне Веларионов. После него владения перешли к сыну Борросу, который в Танце выбрал уже «зелёных».' },
  { id: 'jocelyn', p: 'rogar', par: ['rogar', 'alyssa_v'], hs: 'bar', name: 'Джоселин Баратеон', en: 'Jocelyn Baratheon', k: 'T', b: '54', sp: [['aemon_j', '70 г.']],
    t: 'Дочь Рогара Баратеона и Алиссы Веларион, родившаяся ценой жизни матери. Была единоутробной сестрой Джейехериса I и Алисанны. Вышла за их сына Эймона и стала матерью Рейенис, будущей жены Корлиса. Этот брак соединил королевскую ветвь с Баратеонами ещё до Танца драконов.' },
  { id: 'borros', p: 'boremund', hs: 'bar', name: 'Боррос Баратеон', en: 'Borros Baratheon', k: 'T', d: '131', sp: [['Эленда Карон']],
    t: 'Сын Боремунда и лорд Штормового Предела в Танце драконов. В отличие от отца, поддержал Эйгона II, рассчитывая на выгодный брак одной из дочерей. В его замке встретились Эймонд и Люцерис, но убийство произошло уже после вылета, над заливом Разбитых Кораблей. В конце войны Боррос повёл войско на столицу и погиб от руки Кермита Талли в битве на Королевском тракте.' },
  { id: 'cassandra', p: 'borros', par: ['borros', 'Эленда Карон'], hs: 'bar', name: 'Кассандра Баратеон', en: 'Cassandra Baratheon', k: 'T', sp: [['aegon2', 'помолвка', 'b'], ['сир Уолтер Браунхилл']],
    t: 'Старшая дочь Борроса, одна из сестёр, прозванных Четырьмя Бурями. После смерти Хелейны её обручили с Эйгоном II, однако король погиб до свадьбы. Позднее вышла за сира Уолтера Браунхилла. Её брачные планы отражают попытки Баратеонов сохранить влияние после поражения «зелёных».' },
  { id: 'maris', p: 'borros', par: ['borros', 'Эленда Карон'], hs: 'bar', name: 'Марис Баратеон', en: 'Maris Baratheon', k: 'T',
    t: 'Дочь Борроса Баратеона, одна из Четырёх Бурь. По рассказу хроники, насмешкой над Эймондом подогрела его гнев после отъезда Люцериса из Штормового Предела. Позднее стала молчаливой сестрой. Рассказ о её словах не отменяет ответственности самого Эймонда за последующие события.' },
  { id: 'ellyn', p: 'borros', par: ['borros', 'Эленда Карон'], hs: 'bar', name: 'Эллин Баратеон', en: 'Ellyn Baratheon', k: 'T',
    t: 'Дочь Борроса Баратеона и одна из Четырёх Бурь. Вместе с сёстрами рассматривалась как возможная невеста Эймонда, когда отец обсуждал союз с «зелёными». Её личная биография почти не раскрыта. Достоверно расширить сведения о её дальнейшей жизни не удаётся.' },
  { id: 'floris', p: 'borros', par: ['borros', 'Эленда Карон'], hs: 'bar', name: 'Флорис Баратеон', en: 'Floris Baratheon', k: 'T', sp: [['лорд Таддеус Рован']],
    t: 'Младшая из четырёх дочерей Борроса, известных как Четыре Бури. Позднее вышла за лорда Таддеуса Рована, связав Штормовой Предел с одним из домов Простора. В хрониках появляется главным образом в связи с брачной политикой семьи. Её собственная роль в событиях описана мало.' },
  { id: 'royce', p: 'borros', par: ['borros', 'Эленда Карон'], hs: 'bar', name: 'Ройс Баратеон', en: 'Royce Baratheon', k: 'T',
    t: 'Единственный сын Борроса, родившийся уже после гибели отца. Стал наследником Штормового Предела, пока владением управляла его мать Эленда Карон. Его младенчество пришлось на завершение Танца драконов. Через него продолжилась мужская линия Баратеонов после войны.' },
  { id: 'lord_b208', hs: 'bar', name: 'Лорд Баратеон', full: 'Лорд Баратеон (около 208 г.)', k: 'T',
    t: 'Безымянный лорд Штормового Предела времён Дейерона II. Известен как отец Гоуэна Баратеона; его точная связь с другими представителями поколения, включая Лайонела, раскрыта не полностью. Непрерывная цепочка от Борроса до этой семьи в источниках отсутствует.' },
  { id: 'lyonel', p: 'lord_b208', unc: 1, par: ['lord_b208 (по-видимому)'], hs: 'bar', name: 'Лайонел Баратеон', full: 'Лайонел Баратеон, Смеющийся Шторм', en: 'Lyonel Baratheon, the Laughing Storm', k: 'T', b: '174–194', d: '239–245',
    t: 'Лорд Штормового Предела, известный как Смеющийся Шторм и участник турнира в Эшфорде. В Суде семерых поддержал Дункана Высокого. Когда принц Дункан отверг его дочь, поднял мятеж и объявил себя Штормовым королём. Мир восстановили после его поединка с Дунканом Высоким и договорённости о браке Ормунда с Рейелль Таргариен.' },
  { id: 'gowen', p: 'lord_b208', hs: 'bar', name: 'Гоуэн Баратеон', en: 'Gowen Baratheon', k: 'T', sp: [['tya']],
    t: 'Третий сын одного из лордов Штормового Предела, муж Тии Ланнистер. Этот брак связывал два великих дома задолго до свадьбы Роберта и Серсеи. Их единственный известный сын умер младенцем. Другие подробности жизни Гоуэна в источниках почти отсутствуют.' },
  { id: 'lyonel_d', p: 'lyonel', hs: 'bar', name: 'Дочь Лайонела', full: 'Дочь Лайонела Баратеона', k: 'T', sp: [['duncan', 'разорванная помолвка', 'b']],
    t: 'Безымянная дочь Лайонела Баратеона, обручённая с наследником Эйгона V принцем Дунканом. Дункан выбрал Дженни из Старых Камней и отказался от обещанного брака. Оскорбление стало причиной восстания Лайонела. Имя девушки и её дальнейшая судьба не раскрыты.' },
  { id: 'ormund', p: 'lyonel', hs: 'bar', name: 'Ормунд Баратеон', en: 'Ormund Baratheon', k: 'T', d: '260', sp: [['rhaelle', '245 г.']],
    t: 'Сын Лайонела, лорд Штормового Предела и муж Рейелль Таргариен. Этот брак примирил Баратеонов с короной после мятежа отца. При Джейехерисе II занимал пост десницы и возглавлял королевские силы в Войне Девятигрошовых королей. Погиб на Ступенях от руки Мейлиса Блэкфайра; его сын Стеффон унаследовал Штормовой Предел.' },
  { id: 'steffon', p: 'ormund', par: ['ormund', 'rhaelle'], hs: 'bar', name: 'Стеффон Баратеон', en: 'Steffon Baratheon', k: 'T', b: '246', d: '278', sp: [['Кассана Эстермонт']],
    t: 'Сын Ормунда и Рейелль, лорд Штормового Предела и двоюродный брат Эйериса II. Был отцом Роберта, Станниса и Ренли. По поручению короля отправился в Эссос искать невесту для Рейегара, но на обратном пути его корабль погиб в шторме у родных берегов. Вместе со Стеффоном утонула жена Кассана Эстермонт; Роберт и Станнис видели кораблекрушение из замка.' },
  { id: 'robert', p: 'steffon', par: ['steffon', 'Кассана Эстермонт'], hs: 'bar', name: 'Роберт I', full: 'Роберт I Баратеон', en: 'Robert Baratheon', k: 'K', r: '283–298', b: '262', d: '298', pr: 'aerys2', su: 'joffrey_b', sp: [['cersei', '284 г.'], ['lyanna', 'помолвка', 'b']],
    t: 'Лорд Штормового Предела, возглавивший восстание против Эйериса II вместе с Эддардом Старком и Джоном Арреном. Победил Рейегара на Трезубце и стал королём, подкрепив победу родством с Таргариенами через бабушку Рейелль. Был успешнее как воин, чем как правитель, оставляя государственные дела советникам. Погиб после нападения вепря на охоте; его смерть открыла борьбу за престол.' },
  { id: 'stannis', p: 'steffon', par: ['steffon', 'Кассана Эстермонт'], hs: 'bar', name: 'Станнис Баратеон', en: 'Stannis Baratheon', k: 'C', b: '264', sp: [['Селиса Флорент']],
    t: 'Средний сын Стеффона, удержавший Штормовой Предел во время осады в восстании Роберта. Получил от брата Драконий Камень и служил мастером над кораблями. После смерти Роберта заявил, что дети Серсеи рождены от Джейме, и потребовал корону как законный наследник. После поражения на Черноводной продолжил борьбу; в книгах пришёл на помощь Ночному Дозору и воюет против Болтонов на Севере.' },
  { id: 'renly', p: 'steffon', par: ['steffon', 'Кассана Эстермонт'], hs: 'bar', name: 'Ренли Баратеон', en: 'Renly Baratheon', k: 'C', b: '277', d: '299', sp: [['margaery']],
    t: 'Младший брат Роберта и Станниса, лорд Штормового Предела и мастер над законами. Был близок с Лорасом Тиреллом и женился на его сестре Маргери. После смерти Роберта провозгласил себя королём, опираясь на поддержку Штормовых земель и Простора, хотя права Станниса были старше. Убит сверхъестественной тенью, связанной со Станнисом и Мелисандрой.' },
  { id: 'joffrey_b', p: 'robert', unc: 1, rp: 'jaime', par: ['robert (официально)', 'cersei', 'jaime (на деле)'], hs: 'bar', name: 'Джоффри I', full: 'Джоффри I Баратеон', en: 'Joffrey Baratheon', k: 'K', r: '298–300', b: '286', d: '300', pr: 'robert', su: 'tommen', sp: [['margaery']],
    t: 'Старший сын Серсеи и Джейме, официально считавшийся наследником Роберта Баратеона. После смерти Роберта занял престол и приказал казнить Эддарда Старка, сорвав попытку мирного урегулирования. Его жестокость осложняла положение даже собственных сторонников. Был отравлен на свадебном пиру с Маргери Тирелл; обвинение в убийстве предъявили Тириону.' },
  { id: 'myrcella', p: 'robert', unc: 1, rp: 'jaime', par: ['robert (официально)', 'cersei', 'jaime (на деле)'], hs: 'bar', name: 'Мирцелла', full: 'Мирцелла Баратеон', k: 'T', b: '290', sp: [['trystane', 'помолвка', 'b']],
    t: 'Дочь Серсеи и Джейме, признанная при жизни Роберта его дочерью. По договору Тириона отправлена в Дорн и обручена с Тристаном Мартеллом. Арианна пыталась сделать её королевой, опираясь на дорнийское наследование, при котором старшая дочь стоит перед младшим сыном. Заговор провалился, а Мирцелла получила тяжёлую рану и лишилась уха. В книгах она остаётся жива.' },
  { id: 'tommen', p: 'robert', unc: 1, rp: 'jaime', par: ['robert (официально)', 'cersei', 'jaime (на деле)'], hs: 'bar', name: 'Томмен I', full: 'Томмен I Баратеон', k: 'K', rm: 'на троне с 300', b: '291', pr: 'joffrey_b', sp: [['margaery']],
    t: 'Младший сын Серсеи и Джейме, официально принадлежащий к дому Баратеонов. Унаследовал Железный трон после смерти Джоффри и женился на Маргери. Ещё слишком юн, чтобы управлять самостоятельно, поэтому вокруг него борются за влияние Серсея, Тиреллы и королевский совет. В опубликованных романах остаётся королём и живым ребёнком.' },
  { id: 'mya_stone', p: 'robert', hs: 'bar', name: 'Мия Стоун', en: 'Mya Stone', k: 'R',
    t: 'Внебрачная дочь Роберта, родившаяся в Долине в годы его юности. Работает проводницей и водит мулов по трудной дороге к Орлиному Гнезду. Уверенно чувствует себя в горах, но происхождение бастарда ограничивает её возможности выгодного брака. Её судьба показывает, насколько мало королевское отцовство может значить без официального положения.' },
  { id: 'gendry', p: 'robert', hs: 'bar', name: 'Джендри', en: 'Gendry', k: 'R',
    t: 'Внебрачный сын Роберта, выросший подмастерьем оружейника в Королевской Гавани и не знающий своего происхождения. После смерти короля бежал из столицы вместе с отрядом Йорена, затем встретил Арью и Братство без знамён. В книгах был посвящён в рыцари Бериком Дондаррионом. Часть его сериалного сюжета заимствована у другого бастарда Роберта, Эдрика Шторма.' },
  { id: 'edric', p: 'robert', par: ['robert', 'Делена Флорент'], hs: 'bar', name: 'Эдрик Шторм', en: 'Edric Storm', k: 'R',
    t: 'Сын Роберта и Делены Флорент, единственный его бастард, признанный открыто благодаря знатному происхождению матери. Воспитывался в Штормовом Пределе под защитой Кортни Пенроза. После захвата замка Станнисом оказался на Драконьем Камне, где его жизнь поставили под угрозу планы Мелисандры. Давос помог ему бежать за Узкое море.' },
  { id: 'bella', p: 'robert', hs: 'bar', name: 'Белла', en: 'Bella', k: 'R',
    t: 'Девушка из Каменной Септы, называющая себя внебрачной дочерью Роберта. Её мать связывала зачатие с пребыванием Роберта в городе во время восстания. Встречает Арью и её спутников в заведении «Персик». Её отцовство заявлено самой Беллой и не подтверждено независимо.' },
  { id: 'barra', p: 'robert', hs: 'bar', name: 'Барра', en: 'Barra', k: 'R', d: '298',
    t: 'Маленькая дочь Роберта и молодой женщины по имени Мэган из Королевской Гавани. Эддард видел ребёнка, когда расследовал происхождение королевских детей. После смерти Роберта Барру убили вместе с матерью во время расправы над его бастардами. Она не имела политической роли, но стала жертвой борьбы за сохранение тайны Серсеи.' },
  { id: 'shireen', p: 'stannis', par: ['stannis', 'Селиса Флорент'], hs: 'bar', name: 'Ширен', full: 'Ширен Баратеон', k: 'T', b: '289',
    t: 'Единственная дочь Станниса и Селисы Флорент. В детстве перенесла серую хворь, оставившую след на лице, но болезнь удалось остановить. Любит книги и дружит с Пестряком, живёт под защитой отца и его сторонников. В опубликованных романах находится в Чёрном замке и остаётся жива; её гибель на костре относится к сериалу.' },

  // ——— Дом Арренов
  { id: 'sharra', hs: 'arr', name: 'Шарра Аррен', en: 'Sharra Arryn', k: 'T',
    t: 'Королева-регент Горы и Долины при своём маленьком сыне Роннеле. Во время Завоевания рассчитывала защитить Долину её горами и крепостями, но Висенья на Вхагар прилетела прямо во двор Орлиного Гнезда. Увидев сына рядом с драконьей всадницей, Шарра признала власть Эйгона. Сдача замка позволила сохранить семью и владения без разрушительной войны.' },
  { id: 'ronnel_k', p: 'sharra', hs: 'arr', name: 'Роннел Аррен', full: 'Роннел Аррен, Король, который летал', en: 'Ronnel Arryn, the King Who Flew', k: 'T', d: '37', sp: [['torrhen_d', 'брак устроила Рейенис Таргариен']],
    t: 'Последний король Горы и Долины, признавший власть Эйгона Завоевателя ещё ребёнком. После сдачи Орлиного Гнезда получил обещанный полёт на Вхагар с Висеньей, а позднее правил уже как лорд Аррен. Женился на дочери Торрхена Старка. В 37 году его брат Джонос захватил замок и убил Роннела вместе с женой и детьми.' },
  { id: 'ronnel_kids', p: 'ronnel_k', par: ['ronnel_k', 'torrhen_d'], hs: 'arr', name: 'Дети Роннела', full: 'Дети Роннела Аррена', k: 'T', d: '37',
    t: 'Безымянные дети Роннела Аррена и дочери Торрхена Старка. Погибли вместе с родителями после захвата Орлиного Гнезда Джоносом в 37 году. Их смерть оборвала прямую линию последнего короля Горы и Долины. Имена и возраст детей не названы.' },
  { id: 'jonos', p: 'sharra', hs: 'arr', name: 'Джонос Аррен', full: 'Джонос Аррен, Братоубийца', en: 'Jonos Arryn, the Kinslayer', k: 'T', d: '37',
    t: 'Младший брат Роннела Аррена, воспользовавшийся беспорядками после смерти Эйгона I. Захватил Орлиное Гнездо, убил брата с семьёй и объявил себя королём. Против него выступили верные короне силы, а Мейгор прилетел на Балерионе. Сторонники Джоноса выдали его победителям, после чего он был повешен.' },
  { id: 'hubert', hs: 'arr', name: 'Хьюберт Аррен', en: 'Hubert Arryn', k: 'T', sp: [['дама из дома Ройсов']],
    t: 'Родственник Роннела и Джоноса Арренов, получивший Орлиное Гнездо после гибели обоих братьев. Продолжил главную линию дома Арренов. Был женат на женщине из дома Ройсов и имел шестерых сыновей. Вероятное отцовство по отношению к отдельным поздним Арренам не следует считать полностью установленным.' },
  { id: 'darnold', p: 'hubert', unc: 1, par: ['родство с Хьюбертом в книгах не указано'], hs: 'arr', name: 'Дарнольд Аррен', en: 'Darnold Arryn', k: 'T', d: '54',
    t: 'Лорд Орлиного Гнезда в начале правления Джейехериса I. Погиб во время столкновения с горными кланами вместе со своим братом Раймондом. После этой двойной потери владения перешли к десятилетнему Родрику, сыну Раймонда. Событие показывает, что горные кланы оставались угрозой даже для правящего дома Долины.' },
  { id: 'rymond', p: 'hubert', unc: 1, par: ['родство с Хьюбертом в книгах не указано'], hs: 'arr', name: 'Раймонд Аррен', full: 'Сир Раймонд Аррен', en: 'Rymond Arryn', k: 'T', d: '54',
    t: 'Брат лорда Дарнольда Аррена и отец Родрика. Погиб вместе с братом в борьбе с горными кланами Долины. Его малолетний сын оказался наследником Орлиного Гнезда. Сам Раймонд не успел стать лордом, но через него продолжилась правящая ветвь.' },
  { id: 'rodrik', p: 'rymond', hs: 'arr', name: 'Родрик Аррен', en: 'Rodrik Arryn', k: 'T', b: '44', sp: [['первая жена', 'имя неизвестно'], ['daella_j', '80 г.']],
    t: 'Лорд Орлиного Гнезда, унаследовавший владения в десять лет после гибели отца и дяди. Долгое время служил мастером над законами Джейехериса I. Овдовев, женился на принцессе Дейелле, которая родила ему Эймму и вскоре умерла. Через Эймму Родрик стал дедом Рейениры Таргариен.' },
  { id: 'elys_a', p: 'rodrik', par: ['rodrik', 'первая жена Родрика'], hs: 'arr', name: 'Элис Аррен', en: 'Elys Arryn', k: 'T',
    t: 'Дочь Родрика Аррена от первого брака, старшая единокровная сестра Эйммы. Принадлежала к семье лорда Орлиного Гнезда до его союза с Дейеллой Таргариен. Её личная жизнь в хрониках почти не раскрыта. Имя сохраняется прежде всего как часть родословной Арренов.' },
  { id: 'amanda_a', p: 'rodrik', par: ['rodrik', 'первая жена Родрика'], hs: 'arr', name: 'Аманда Аррен', en: 'Amanda Arryn', k: 'T',
    t: 'Дочь Родрика Аррена от первого брака и единокровная сестра Эйммы, будущей королевы. В источниках названа среди детей лорда Орлиного Гнезда. Достоверных сведений о её браке, потомках или политической роли нет. Поэтому её карточка остаётся краткой.' },
  { id: 'jeyne_f', p: 'rodrik', unc: 1, par: ['rodrik (вероятно)', 'первая жена Родрика'], hs: 'arr', name: 'Лорд Аррен', full: 'Лорд Аррен, отец Джейны', k: 'T', d: '97',
    t: 'Безымянный отец Джейны Аррен, лорд Орлиного Гнезда, чьё точное положение среди потомков Родрика не раскрыто полностью. В 97 году погиб вместе с сыновьями от рук Каменных Воронов, одного из горных кланов. После этого владения унаследовала маленькая Джейна. Его имя и самостоятельная биография не сохранились.' },
  { id: 'rodrik_s2', p: 'rodrik', unc: 1, par: ['rodrik (вероятно)', 'первая жена Родрика'], hs: 'arr', name: 'Второй сын Родрика', full: 'Второй сын Родрика Аррена', k: 'T',
    t: 'Безымянный представитель ветви Арренов, из которой происходил Арнольд, двоюродный брат Джейны. Его положение в семье Родрика восстановлено предположительно. Источники не дают достаточных сведений, чтобы уверенно назвать его родителей и все семейные связи.' },
  { id: 'aemma', p: 'rodrik', par: ['rodrik', 'daella_j'], hs: 'arr', name: 'Эймма Аррен', en: 'Aemma Arryn', k: 'T', b: '82', d: '105', sp: [['viserys1', '93 г.']],
    t: 'Дочь Родрика Аррена и Дейеллы Таргариен, внучка Джейехериса I по матери. Вышла за Визериса и стала матерью Рейениры, единственного их ребёнка, пережившего младенчество. Несколько беременностей закончились потерями. В 105 году умерла при рождении сына Бейлона, который также вскоре погиб; после этого Визерис объявил наследницей Рейениру.' },
  { id: 'jeyne', p: 'jeyne_f', hs: 'arr', name: 'Джейна Аррен', full: 'Джейна Аррен, Дева Долины', en: 'Jeyne Arryn, the Maiden of the Vale', k: 'T', b: '94', d: '134',
    t: 'Леди Орлиного Гнезда, унаследовавшая Долину после гибели отца и братьев. Должна была защищать своё право править от родственников, считавших мужчину более подходящим наследником. В Танце поддержала Рейениру и предоставила убежище Рейене, дочери Деймона. После войны участвовала в регентстве Эйгона III, а её смерть вызвала новый спор о наследовании Долины.' },
  { id: 'jeyne_br', p: 'jeyne_f', hs: 'arr', name: 'Братья Джейны', full: 'Братья Джейны Аррен', k: 'T', d: '97',
    t: 'Безымянные братья Джейны Аррен, погибшие вместе с отцом в 97 году. На их семью напали Каменные Вороны из горных кланов. После гибели мужчин Орлиное Гнездо перешло к Джейне. Количество, имена и возраст братьев подробно не указаны.' },
  { id: 'arnold', p: 'rodrik_s2', unc: 1, par: ['двоюродный брат Джейны; отец не назван'], hs: 'arr', name: 'Арнольд Аррен', full: 'Сир Арнольд Аррен, Безумный наследник', en: 'Arnold Arryn, the Mad Heir', k: 'T',
    t: 'Двоюродный брат Джейны Аррен, оспаривавший её право владеть Орлиным Гнездом. Дважды пытался отстранить её и был заключён в темницу. После её смерти притязания этой ветви снова стали причиной войны за наследство. Его история связана с сопротивлением женскому правлению в Долине.' },
  { id: 'eldric', p: 'arnold', hs: 'arr', name: 'Элдрик Аррен', full: 'Сир Элдрик Аррен', en: 'Eldric Arryn', k: 'T',
    t: 'Сын Арнольда Аррена, заявивший права на Орлиное Гнездо после смерти Джейны. Выступал против наследника, названного в её завещании, Джоффри Аррена. Во время борьбы за Долину был схвачен и казнён сиром Корвином Корбреем. Его претензия стала одной из нескольких, расколовших регион после войны.' },
  { id: 'joffrey_a', hs: 'arr', name: 'Джоффри Аррен', en: 'Joffrey Arryn', k: 'T', par: ['дальний кузен Джейны; линия не прослежена'],
    t: 'Дальний родственник Джейны Аррен и рыцарь Кровавых ворот. Она назначила его наследником в завещании, однако другие ветви дома отказались принять это решение. После её смерти ему пришлось бороться за Орлиное Гнездо. Его права поддержала корона, но признание лордом потребовало военной силы.' },
  { id: 'isembard', hs: 'arr', name: 'Изембард Аррен', en: 'Isembard Arryn', k: 'T', par: ['глава Арренов из Чаячьего города'],
    t: 'Богатый представитель младшей ветви Арренов из Чаячьего города. После смерти Джейны заявил собственные права на Орлиное Гнездо, соперничая с Джоффри и ветвью Арнольда. Его положение опиралось на влияние и средства городской семьи. Этот спор показал разницу между старшей лордской линией и её состоятельными родственниками.' },
  { id: 'donnel', hs: 'arr', name: 'Доннел Аррен', en: 'Donnel Arryn', k: 'T', par: ['родство с предыдущими лордами в книгах не прослежено'],
    t: 'Лорд Орлиного Гнезда при Дейероне II. В Первом восстании Блэкфайров командовал авангардом королевской армии на Краснотравном поле; подкрепление Гвейна Корбрея помогло ему избежать разгрома. В 209 году закрыл проходы и морское сообщение с Долиной, защищая её от Великого весеннего мора. Его решения сохранили регион от эпидемии.' },
  { id: 'alys_r', hs: 'arr', name: 'Алис Аррен', full: 'Алис Аррен, жена Рейегеля', en: 'Alys Arryn', k: 'T', par: ['родители в книгах не названы'], sp: [['rhaegel']],
    t: 'Представительница дома Арренов, жена принца Рейегеля Таргариена. Родила близнецов Эйлора и Эйлору и младшую дочь Дейенору. После смерти Рейегеля её дети оказались в очереди на престол Эйериса I. Через Дейенору Алис была бабушкой Мейгора, младенца, чьи права отверг Великий совет 233 года.' },
  { id: 'jasper', hs: 'arr', name: 'Джаспер Аррен', en: 'Jasper Arryn', k: 'T', par: ['родители в книгах не названы'],
    t: 'Лорд Орлиного Гнезда и отец Джона, Роннела и Алис Аррен. Через его детей проходит родословная Джона Аррена и будущего наследника Гарольда Хардинга. Подробности собственного правления Джаспера почти не раскрыты. Его роль в древе прежде всего связывает старшее поколение с семьёй времён восстания Роберта.' },
  { id: 'jon_a', p: 'jasper', hs: 'arr', name: 'Джон Аррен', en: 'Jon Arryn', k: 'T', d: '298', wd: ['robert', 'eddard'],
    sp: [['Джейна Ройс', 'умерла в родах'], ['Ровена Аррен', 'кузина'], ['lysa']],
    t: 'Лорд Орлиного Гнезда и воспитатель Эддарда Старка и Роберта Баратеона. Отказался выдать их Эйерису II и поднял Долину, став одним из главных руководителей восстания. После победы служил десницей Роберта и вместе со Станнисом расследовал происхождение детей Серсеи. Был отравлен собственной женой Лизой по наущению Петира Бейлиша, что долго оставалось тайной.' },
  { id: 'ronnel_j', p: 'jasper', hs: 'arr', name: 'Роннел Аррен', full: 'Роннел Аррен, брат Джона', k: 'T', sp: [['дама из дома Белморов']],
    t: 'Младший брат Джона Аррена, хранитель Лунных врат и отец Элберта. Не дожил до восстания Роберта, умерев от болезни живота. Его сын некоторое время был наследником бездетного Джона, но позднее погиб по приказу Эйериса II. Эти потери сделали порядок наследования Арренов особенно уязвимым.' },
  { id: 'alys_j', p: 'jasper', hs: 'arr', name: 'Алис Аррен', full: 'Алис Аррен, сестра Джона', k: 'T', sp: [['сир Элис Уэйнвуд']],
    t: 'Сестра Джона и Роннела Арренов, жена сира Элиса Уэйнвуда. Родила сына и восемь дочерей, однако большинство их линий пресеклось или не могло дать наследника Орлиному Гнезду. Её младшая дочь стала матерью Гарольда Хардинга. Благодаря этому родству Гарольд считается следующим наследником после Роберта Аррена.' },
  { id: 'robert_a', p: 'jon_a', par: ['jon_a', 'lysa'], hs: 'arr', name: 'Роберт Аррен', en: 'Robert Arryn, Sweetrobin', k: 'T', b: '292',
    t: 'Единственный выживший сын Джона Аррена и Лизы Талли. После смерти отца унаследовал Орлиное Гнездо, но остаётся болезненным ребёнком, зависимым от взрослых. После гибели матери оказался под властью Петира Бейлиша. В книгах его зовут Роберт, тогда как сериал использует имя Робин; положение мальчика важно для планов Мизинца в Долине.' },
  { id: 'elbert', p: 'ronnel_j', par: ['ronnel_j', 'дама из дома Белморов'], hs: 'arr', name: 'Элберт Аррен', full: 'Сир Элберт Аррен', en: 'Elbert Arryn', k: 'T', d: '282',
    t: 'Сын Роннела Аррена и наследник своего дяди Джона до рождения Роберта. Приехал в Королевскую Гавань вместе с Брандоном Старком, требовавшим ответа за исчезновение Лианны. Эйерис II приказал казнить спутников Брандона. Смерть Элберта стала для Джона Аррена личной потерей накануне восстания.' },
  { id: 'jasper_w', p: 'alys_j', par: ['сир Элис Уэйнвуд', 'alys_j'], hs: 'oth', h: 'Уэйнвудов', name: 'Джаспер Уэйнвуд', en: 'Jasper Waynwood', k: 'T',
    t: 'Единственный сын Алис Аррен и сира Элиса Уэйнвуда. Умер в детстве и не оставил потомков. Поэтому возможная линия наследования Орлиного Гнезда через Алис продолжилась через её дочерей. Другие сведения о мальчике отсутствуют.' },
  { id: 'waynwood_e', p: 'alys_j', par: ['сир Элис Уэйнвуд', 'alys_j'], hs: 'oth', h: 'Уэйнвудов', name: 'Старшая дочь Алис', full: 'Старшая дочь Алис Аррен', k: 'T', sp: [['denys']],
    t: 'Старшая дочь Алис Аррен и Элиса Уэйнвуда. Вышла за сира Дениса Аррена, дальнего родственника главной линии. После его гибели в Битве колоколов их маленький сын также умер. Её имя не названо, а эта ветвь не дала выжившего наследника Орлиному Гнезду.' },
  { id: 'waynwood_m', p: 'alys_j', par: ['сир Элис Уэйнвуд', 'alys_j'], hs: 'oth', h: 'Уэйнвудов', name: 'Ещё шесть дочерей', full: 'Шесть средних дочерей Алис Аррен', k: 'T',
    t: 'Шесть средних дочерей Алис Аррен и Элиса Уэйнвуда, объединённых здесь из-за отсутствия имён. Две умерли, одна стала септой, другая молчаливой сестрой, одна осталась бездетной, ещё одну похитили горцы. Эти обстоятельства объясняют, почему права Арренов в итоге связывают с сыном самой младшей сестры. Подробности отдельных судеб неизвестны.' },
  { id: 'waynwood_y', p: 'alys_j', par: ['сир Элис Уэйнвуд', 'alys_j'], hs: 'oth', h: 'Уэйнвудов', name: 'Младшая дочь Алис', full: 'Младшая дочь Алис Аррен', k: 'T', sp: [['рыцарь из дома Хардингов']],
    t: 'Младшая дочь Алис Аррен и Элиса Уэйнвуда, вышедшая за представителя дома Хардингов. Её сын Гарольд через неё получил родство с главной линией Арренов. После пресечения других ветвей это родство сделало его вероятным наследником Орлиного Гнезда. Имени самой женщины источники не сообщают.' },
  { id: 'denys', hs: 'arr', name: 'Денис Аррен', full: 'Сир Денис Аррен, Любимец Долины', en: 'Denys Arryn', k: 'T', d: '283', par: ['дальний родственник Джона; линия не прослежена'], sp: [['waynwood_e']],
    t: 'Дальний родственник Джона Аррена и известный рыцарь, женатый на одной из дочерей Алис Аррен. Считался возможным наследником после гибели Элберта. Во время восстания Роберта погиб в Битве колоколов от руки Джона Коннингтона. Его маленький сын вскоре тоже умер, и эта линия наследования оборвалась.' },
  { id: 'denys_son', p: 'denys', par: ['denys', 'waynwood_e'], hs: 'arr', name: 'Сын Дениса', full: 'Сын Дениса Аррена', k: 'T',
    t: 'Маленький сын Дениса Аррена и безымянной дочери Алис Аррен. После гибели отца мог сохранять права своей ветви на Орлиное Гнездо. Однако вскоре умер сам, не оставив потомства. Имени и точного возраста ребёнка источники не дают.' },
  { id: 'harrold', p: 'waynwood_y', par: ['рыцарь из дома Хардингов', 'waynwood_y'], hs: 'oth', h: 'Хардингов', name: 'Гарольд Хардинг', full: 'Гарольд Хардинг, Гарри Наследник', en: 'Harrold Hardyng, Harry the Heir', k: 'T',
    t: 'Сын Хардинга и внучки Джаспера Аррена, известный как Гарри Наследник. Через мать происходит от Алис Аррен и считается следующим претендентом на Орлиное Гнездо после Роберта. Воспитывался у Аньи Уэйнвуд и был посвящён в рыцари. Петир Бейлиш рассчитывает использовать его возможный брак с Сансой для своих планов в Долине и на Севере.' }
];
